export function renderGridView(
  container: HTMLElement,
  scheduledDate: string,
  options?: {
    headerActions?: HTMLElement[];
    titleLeadingActions?: HTMLElement[];
    titleSlot?: HTMLElement;
    activeStripVisible?: boolean;
    /** Whether the sidebar (catalog / Scheduled panel) starts expanded. */
    catalogVisible?: boolean;
    bulkMode?: boolean;
    onBulkModeChange?: (enabled: boolean) => void;
    onClearSchedule?: (target: HTMLElement) => void;
    planContext?: { scenarioId: string; tournamentId: string } | null;
  },
): void {
  syncVisibilityDate(scheduledDate);
  currentDate = scheduledDate;
  sidebarVisible = options?.catalogVisible ?? true;
  sidebarTab = null;
  planContext = options?.planContext ?? null;
  if (planContext) ensurePlanModeStyles();
  actionBarContainer = container;
  clearStaleDrawBanner();
  destroyVisibilityTip();

  // Holds the action bar's live updater so refresh() can re-render the issues
  // cluster in place after a schedule change. Assigned once the bar is built.
  let gridActionBar: GridActionBar | null = null;

  // Late-binding refresh: grid cells reference this via closure, but grid is built
  // before activeControl exists. The wrapper defers to the real refresh once ready.
  function refresh(): void {
    if (!activeControl || !grid) return;
    const control = activeControl;
    grid.rebuild(currentDate);
    const freshIssues = buildIssues(currentDate);
    // One store notification for the three pushes. Each write notified on its own (four with the
    // selection re-point), and every notification re-rendered the Inspector, which grades the
    // selected matchUp's readiness, rest and timing through the engine, plus the issues and dates.
    control.batch(() => {
      control.setMatchUpCatalog(buildCatalog(currentDate));
      control.setScheduleDates(buildScheduleDates(currentDate));
      control.setIssues(freshIssues);
    });
    // Surface new/cleared conflicts (e.g. a drag that puts court times out of
    // order) in the action bar's issues button without rebuilding the bar.
    gridActionBar?.setIssues(freshIssues);
    gridActionBar?.setTimingAvailable(hasCallTimingData());
    // The venue-frame pill is removed by its own action — setting the zone from
    // the notice's modal makes the notice obsolete, so it has to be re-evaluated
    // on the same refresh that re-frames the clocks.
    gridActionBar?.setVenueFrame();
    refreshActiveStrip(currentDate);
  }
  currentRefresh = refresh;

  // The Inspector's schedule actions dispatch through here rather than calling
  // `mutationRequest` themselves — `executeMethods` is what honours plan mode,
  // bulk mode and the deleted-draw check. See `scheduleMutationControl`.
  registerScheduleMutationControl({ execute: (methods) => executeMethods(methods, refresh) });

  const gridCallbacks: GridCallbacks = { onRefresh: refresh, executeMethods };

  const catalog = buildCatalog(scheduledDate);
  const scheduleDates = buildScheduleDates(scheduledDate);
  const grid = buildInteractiveGrid(scheduledDate, gridCallbacks);
  const issues = buildIssues(scheduledDate);

  // ── Active Strip: one-row court summary above the grid ──
  activeStrip = buildActiveStripPanel(
    {
      onMatchUpDrop: (payload, target, event) => {
        handleActiveStripDrop(payload, target, refresh, event);
      },
    },
    {
      cellHeight: `${STRIP_CELL_HEIGHT_PX}px`,
      // Small label in the leading spacer cell.
      spacerLabel: t('schedule.now'),
      renderCell: (matchUp) => {
        const cellData = matchUp.payload as any;
        if (!cellData) return null;
        const cell = buildScheduleGridCell(mapMatchUpToCellData(cellData), DEFAULT_SCHEDULE_CELL_CONFIG);
        // The strip is where the call-to-court gesture happens, so the check-in state has to be
        // legible HERE and not only back on the catalog card. Never gated by the prompt mode:
        // `off` means "do not interrupt me", not "show me nothing".
        const badge = renderCheckInBadge(matchUp.matchUpId);
        if (badge) cell.appendChild(badge);
        return cell;
      },
    },
  );
  attachStripDropAffordance(activeStrip.element);

  // Wrap strip + grid in a single scroll container so they pan horizontally as
  // one. The grid root's own overflow:auto is overridden — only the wrapper
  // scrolls, ensuring the strip's columns stay aligned with the grid below.
  // The strip is sticky-pinned so it stays visible while the grid scrolls
  // vertically. Grid column headers reference --strip-offset to stick BELOW
  // the strip rather than overlapping it; the offset toggles to 0 when the
  // strip is hidden.
  const gridWrapper = document.createElement('div');
  gridWrapper.style.cssText = 'display: flex; flex-direction: column; height: 100%; min-height: 0; overflow: auto;';
  // +2 accounts for the strip's bottom accent rule.
  gridWrapper.style.setProperty('--strip-offset', `${STRIP_CELL_HEIGHT_PX + 2}px`);
  activeStrip.element.style.position = 'sticky';
  activeStrip.element.style.top = '0';
  activeStrip.element.style.zIndex = '3';
  activeStrip.element.style.flexShrink = '0';
  gridWrapper.appendChild(activeStrip.element);
  grid.element.style.overflow = 'visible';
  grid.element.style.flex = '1';
  grid.element.style.minHeight = '0';
  gridWrapper.appendChild(grid.element);

  const config: SchedulePageConfig = {
    matchUpCatalog: catalog,
    scheduleDates,
    issues,
    courtGridElement: gridWrapper,
    // Built here rather than by each caller: three entry points (schedulingTab, planView,
    // profileView) thread headerActions, and the prompt mode belongs to the schedule surface itself
    // rather than to any one of them.
    headerActions: [buildCheckInModeToggle(), ...(options?.headerActions ?? [])],
    titleLeadingActions: options?.titleLeadingActions,
    titleSlot: options?.titleSlot,
    // Seed the store with the persisted visibility so the very first click
    // dispatches a real state change (default-true store + false-localStorage
    // otherwise causes a no-op on first toggle).
    activeStripVisible: options?.activeStripVisible ?? true,
    // Same reason as activeStripVisible: seed from localStorage so the first
    // click on the toggle dispatches a real change rather than a no-op against
    // the store's default-true.
    inspectorVisible: readInspectorVisible(),
    // Consumer-supplied Inspector detail: rest + readiness for the selected
    // matchUp. A render hook rather than an external append — the Inspector rebuilds its
    // body on every store tick and would wipe anything appended from outside.
    renderInspectorExtra: (matchUp, state) => renderInspectorSections(matchUp, state.selectedDate),
    // The rest and check-in headlines go on the card itself: the "which do I call
    // next" decision is made while scanning the catalog, before any card is selected
    // and before the drag starts, so the Inspector is one interaction too late.
    // Rest asks whether they are fit to be called, check-in whether they are here.
    renderCardExtra: (matchUp) => (catalogOnScreen() ? renderCardBadges(matchUp.matchUpId, currentDate) : null),
    // Hovering a card lights up what it is waiting on, wherever the page draws
    // it. The question a red scheduled time raises is "waiting on WHICH match",
    // and pointing at the grid answers it faster than a sentence can.
    relatedMatchUpIds: (matchUp) => relatedFor(matchUp.matchUpId, currentDate),
    // The store owns `selectedDate`, which the Inspector reads; `currentDate` is
    // what every other surface here reads. They must never name different days —
    // rest computed against day one while the card beside it computed against
    // today is the failure this closes. TMX collapses the component's own date
    // strip, so this fires only if that panel is ever surfaced; wiring it anyway
    // is what makes "one viewed date" a property of the page rather than of the
    // current layout.
    onDateSelected: (date: string) => {
      if (!date || date === currentDate) return;
      currentDate = date;
      refresh();
    },
    // Restore catalog filter state captured from a previous mount within
    // this tournament session. Cleared on tournament load (see loadTournament).
    initialCatalogState: context.scheduleCatalogState,
    hideLeft: true,
    catalogSide: 'left',
    scheduledBehavior: 'dim',
    schedulingMode: 'immediate',

    onMatchUpDrop: (payload, event) => {
      // Walk up from event.target to find the grid cell with data attributes
      let target = event.target as HTMLElement | null;
      while (target && !target.getAttribute(DATA_COURT_ID)) {
        target = target.parentElement;
      }

      const courtId = target?.getAttribute(DATA_COURT_ID);
      const venueId = target?.getAttribute(DATA_VENUE_ID);
      const courtOrder = target?.getAttribute(DATA_COURT_ORDER);

      if (!courtId || !venueId || !courtOrder) return;

      const existingMatchUpId = target?.getAttribute(DATA_MATCHUP_ID);
      const existingDrawId = target?.getAttribute(DATA_DRAW_ID);

      const applyDrop = (overrideScheduleLock?: boolean) => {
        const methods = buildGridDropMethods({
          payload: payload as unknown as GridDropPayload,
          target: {
            courtId,
            venueId,
            courtOrder: Number.parseInt(courtOrder, 10),
            scheduledTime: target?.getAttribute(DATA_SCHEDULED_TIME) ?? undefined,
          },
          occupant: existingMatchUpId ? { matchUpId: existingMatchUpId, drawId: existingDrawId ?? undefined } : null,
          scheduledDate: currentDate,
          overrideScheduleLock,
        });

        if (methods.length) executeMethods(methods, refresh);
      };

      // A drop can move TWO matchUps — the dragged one and the occupant it
      // displaces or swaps with — so both are checked before asking. Warn, then
      // allow: the factory refuses the write without the override, and the lock
      // survives the move either way.
      const { matchUps: liveMatchUps } = getCachedAllMatchUps();
      const byId = (id?: string | null) => (liveMatchUps || []).find((m: any) => m.matchUpId === id);
      const lockedIds = lockedInDrop({
        dragged: byId((payload as unknown as GridDropPayload)?.matchUp?.matchUpId),
        occupant: byId(existingMatchUpId),
      });

      if (lockedIds.length) {
        confirmModal({
          title: t('schedule.lockedMoveTitle'),
          query: t('schedule.lockedMoveConfirm'),
          okIntent: INTENT_WARNING,
          okAction: () => applyDrop(true),
          cancelAction: undefined,
        });
        return;
      }

      applyDrop();
    },

    onMatchUpRemove: (matchUpId) => {
      // Find the matchUp's drawId from the catalog
      const catalog = buildCatalog(currentDate);
      const item = catalog.find((m) => m.matchUpId === matchUpId);

      const methods = [
        {
          method: ADD_MATCHUP_SCHEDULE_ITEMS,
          params: {
            matchUpId,
            drawId: item?.drawId ?? '',
            schedule: { scheduledTime: '', scheduledDate: '', courtOrder: '', venueId: '', courtId: '' },
            removePriorValues: true,
          },
        },
        // Explicit unschedule — clear any prior active-strip "called" stamp.
        {
          method: SET_MATCHUP_CALLED_AT,
          params: { matchUpId, drawId: item?.drawId ?? '', calledAt: null },
        },
      ];

      // Un-start a called/started-but-unscored match: an off-court matchUp must
      // not remain IN_PROGRESS (two live matches in one column is impossible).
      methods.push(...buildUnstartOnRemoveMethods(matchUpId, item?.drawId ?? ''));

      executeMethods(methods, refresh);
    },

    onMatchUpSelected: () => {
      // Selection is store-local: the Inspector reads `state.selectedMatchUp`
      // and re-renders itself. Nothing global to update — the hook stays so a
      // future consumer (deep link, cross-panel highlight) has a seam.
    },
  };

  // Mount the schedule page inside a flex-column wrapper so a bottom
  // action bar (Issues / Bulk mode / Clear) can sit below the panel —
  // mirrors the profile view's action-bar pattern. Without the wrapper,
  // #schedule2Container is plain block layout and the bar would push
  // outside the fixed-height viewport.
  const panelWrapper = document.createElement('div');
  panelWrapper.style.cssText = 'display: flex; flex-direction: column; height: 100%; overflow: hidden;';
  container.appendChild(panelWrapper);

  const panelArea = document.createElement('div');
  panelArea.style.cssText = 'flex: 1; min-height: 0; overflow: hidden;';
  panelWrapper.appendChild(panelArea);

  activeControl = createSchedulePage(config, panelArea);

  // Action bar — always rendered; it owns the min-width stepper even when
  // there are no issues / no bulk toggle / no clear menu. The provider
  // permission check inside buildGridActionBar decides whether the bulk
  // toggle appears.
  const actionBar = buildGridActionBar({
    issues,
    bulkMode: options?.bulkMode ?? false,
    minCourtWidth: readUserMinCourtWidth(),
    onMinCourtWidthChange: (width) => {
      writeUserMinCourtWidth(width);
      refresh();
    },
    onBulkModeChange: options?.onBulkModeChange ?? (() => undefined),
    onClearSchedule: options?.onClearSchedule,
    warningBarsVisible: readGridWarningBars(),
    // `grid.rebuild` rather than `refresh()`: refresh re-renders the issues cluster,
    // which destroys the popover the operator just clicked in. Re-annotating the cells
    // is the whole of the change, and it leaves the list open beside the grid it is
    // explaining. The issue SET is unchanged either way — this hides decoration, not
    // issues — so nothing in the popover goes stale.
    onWarningBarsChange: (visible: boolean) => {
      writeGridWarningBars(visible);
      grid?.rebuild(currentDate);
    },
    // Bulk pin/unpin for the viewed date. Refreshes rather than mutating cells
    // in place: a lock changes the affordance on every affected cell.
    onScheduleLock: (target: HTMLElement) =>
      openScheduleLockMenu({ target, scheduledDate: currentDate, onLocksChanged: refresh }),
    timingAvailable: hasCallTimingData(),
    onOpenTimingReport: openTimingVarianceReport,
    datePublished: isOrderOfPlayDatePublished(currentDate, getOrderOfPlayPublishState()),
    onTogglePublish: () => confirmTogglePublish(),
    // Setting the venue zone re-frames every clock on the page, so redraw.
    onVenueTimeZoneSet: refresh,
  });
  gridActionBar = actionBar;

  // Confirm + apply publish/unpublish of the viewed date's order of play,
  // reusing the same mutation path as the publishing tab. On success the footer
  // pill updates in place; the date selector refreshes via its own
  // onMutationApplied subscription.
  function confirmTogglePublish(): void {
    const publishState = getOrderOfPlayPublishState();
    const fullRange = plainDateRange(
      getCachedCompetitionDateRange().startDate ?? '',
      getCachedCompetitionDateRange().endDate ?? '',
    );
    const { methods, willPublish } = buildOrderOfPlayDateToggleMethods(currentDate, fullRange, publishState);
    const label = formatDateLabel(currentDate);
    confirmModal({
      title: willPublish ? 'Publish order of play' : 'Unpublish order of play',
      query: willPublish
        ? `Publish the order of play for ${label}? It will become visible to the public.`
        : `Unpublish the order of play for ${label}? It will no longer be visible to the public.`,
      okIntent: willPublish ? INTENT_SUCCESS : INTENT_WARNING,
      okAction: () => {
        mutationRequest({
          methods,
          callback: (result: any) => {
            if (result?.error) {
              scheduleToast({ message: t('gridView.publishFailed'), intent: INTENT_DANGER });
              return;
            }
            actionBar.setDatePublished(willPublish);
            scheduleToast({
              message: willPublish ? `Order of play published for ${label}` : `Order of play unpublished for ${label}`,
              intent: willPublish ? INTENT_SUCCESS : INTENT_WARNING,
            });
          },
        });
      },
    });
  }
  panelWrapper.appendChild(actionBar.element);

  // Wire the strip's visibility toggle through the schedule page store, and
  // push the initial data snapshot now that the activeControl exists. We also
  // sync the --strip-offset CSS var on the wrapper so the grid's sticky column
  // headers stick BELOW the strip when it's visible, and at top:0 when hidden.
  const syncStripOffset = (visible: boolean) => {
    gridWrapper.style.setProperty('--strip-offset', visible ? `${STRIP_CELL_HEIGHT_PX + 2}px` : '0px');
  };
  // The "Now" strip is only meaningful today — force it hidden on any other date,
  // regardless of the user's visibility preference.
  const applyStripVisibility = (nextState: any) => {
    const visible = !!nextState.activeStripVisible && scheduledDate === todayIso();
    activeStrip?.update({ ...nextState, activeStripVisible: visible });
    syncStripOffset(visible);
  };
  activeStripUnsubscribe = activeControl.getStore().subscribe((nextState) => {
    applyStripVisibility(nextState);
  });

  // Capture catalog filter changes into context so they survive tab navigation
  // within the same tournament. Cleared on tournament load (see loadTournament
  // in tournamentDisplay.ts). Stored as a fresh object reference on every
  // change so the next renderGridView seeds from the latest snapshot.
  catalogStateUnsubscribe = activeControl.getStore().subscribe((nextState) => {
    context.scheduleCatalogState = {
      catalogSearchQuery: nextState.catalogSearchQuery,
      catalogGroupBy: nextState.catalogGroupBy,
      catalogFilters: nextState.catalogFilters,
      showCompleted: nextState.showCompleted,
      showScheduled: nextState.showScheduled,
    };
  });
  const initialState = activeControl.getStore().getState();
  applyStripVisibility(initialState);
  refreshActiveStrip(currentDate);

  // Periodic refresh of just the courtBlocks portion so availability blocks
  // (PRACTICE / MAINTENANCE / etc.) appear and disappear with the clock.
  // 30s cadence trades a small re-render cost for ~30s worst-case lag.
  if (activeStripBlockTicker) clearInterval(activeStripBlockTicker);
  activeStripBlockTicker = setInterval(() => {
    if (!activeStrip) return;
    refreshActiveStrip(currentDate);
  }, 30000);

  // Strip cell clicks open the same popover as grid-cell clicks. The leading
  // spacer ("Now") opens the bulk Now-row popover. Delegated listener so both
  // survive the strip's render() rebuilds.
  activeStrip.element.addEventListener('click', (e) => {
    const spacer = (e.target as HTMLElement | null)?.closest('.spl-active-strip-spacer');
    if (spacer) {
      handleActiveStripNowClick(e as MouseEvent, buildNowRowContext(refresh));
      return;
    }
    const target = (e.target as HTMLElement | null)?.closest('.spl-active-strip-cell') as HTMLElement | null;
    if (!target) return;
    handleStripCellClick(e as MouseEvent, target, refresh);
  });
  makeSpacerInteractive(activeStrip.element);

  // ── Inject sidebar controls: collapse toggle + Unscheduled/Scheduled tabs ──
  injectSidebarControls(container, refresh);
}

// ============================================================================
// Sidebar Controls (collapse + scheduled matchUp list)
// ============================================================================

function injectSidebarControls(container: HTMLElement, refresh: () => void): void {
  const layout = container.querySelector('.spl-layout') as HTMLElement;
  if (!layout) return;

  // The sidebar is the first child when catalogSide='left'
  const sidebar = layout.firstElementChild as HTMLElement;
  if (!sidebar) return;

  // Build control bar (inspector toggle + tab switcher: Unscheduled / Scheduled)
  const controlBar = document.createElement('div');
  controlBar.style.cssText =
    'display: flex; align-items: center; gap: 4px; padding: 6px 8px; flex-shrink: 0; border-bottom: 1px solid var(--sp-border, var(--tmx-border-primary));';

  // Inspector show/hide, left of the tabs. Global to the catalog: one flag for
  // BOTH views, because the Inspector describes the selected matchUp rather than
  // either tab's contents. Persisted, and NOT auto-revealed on selection — a
  // deliberate operator choice is not overridden (see the workstream plan).
  const inspectorToggle = document.createElement('button');
  inspectorToggle.className = 'tmx-inspector-toggle';
  inspectorToggle.dataset.inspectorToggle = 'true';
  inspectorToggle.innerHTML =
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="15" x2="21" y2="15"/></svg>';

  const syncInspectorToggle = (visible: boolean) => {
    inspectorToggle.setAttribute('aria-pressed', String(visible));
    inspectorToggle.title = visible ? t('schedule.inspector.hide') : t('schedule.inspector.show');
    inspectorToggle.setAttribute('aria-label', inspectorToggle.title);
  };
  syncInspectorToggle(activeControl?.getStore().getState().inspectorVisible ?? readInspectorVisible());

  inspectorToggle.addEventListener('click', () => {
    const store = activeControl?.getStore();
    if (!store) return;
    const next = !store.getState().inspectorVisible;
    store.setInspectorVisible(next);
    writeInspectorVisible(next);
    syncInspectorToggle(next);
  });

  controlBar.appendChild(inspectorToggle);

  const unschedTab = document.createElement('button');
  unschedTab.dataset.sidebarTab = 'unscheduled';
  const schedTab = document.createElement('button');
  schedTab.dataset.sidebarTab = 'scheduled';
  const tabStyle = (active: boolean) =>
    [
      FONT_SIZE_11,
      'padding: 3px 8px',
      'border-radius: 10px',
      'cursor: pointer',
      'border: 1px solid transparent',
      'white-space: nowrap',
      active
        ? 'background: var(--tmx-fill-accent, #2563eb); color: #fff; font-weight: 600;'
        : 'background: var(--sp-chip-bg, rgba(128,128,128,0.12)); color: inherit;',
    ].join('; ');
  // Both Unscheduled and Scheduled tabs carry an inline (n) count badge —
  // populated on initial render and refreshed whenever the store ticks. The
  // badges give operators an at-a-glance hint of how much work remains on
  // each side without switching tabs. Translucent-white background reads
  // legibly against both the active (blue) and inactive (gray) tab fills.
  const badgeCss =
    'display: inline-block; font-size: 0.625rem; font-weight: 700; padding: 0 6px; border-radius: 9px; background: rgba(255,255,255,0.25); color: inherit; min-width: 16px; text-align: center;';

  unschedTab.textContent = t('schedule.unscheduled');
  unschedTab.appendChild(document.createTextNode(' '));
  const unschedBadge = document.createElement('span');
  unschedBadge.style.cssText = badgeCss;
  unschedBadge.textContent = '0';
  unschedTab.appendChild(unschedBadge);

  schedTab.textContent = t('schedule.scheduled');
  schedTab.appendChild(document.createTextNode(' '));
  const schedBadge = document.createElement('span');
  schedBadge.style.cssText = badgeCss;
  schedBadge.textContent = '0';
  schedTab.appendChild(schedBadge);

  controlBar.appendChild(unschedTab);
  controlBar.appendChild(schedTab);

  // Scheduled matchUp list container — same DOM layout as the unscheduled
  // catalog widget (header with title + filter icon, toolbar with search +
  // group-by select, body with grouped cards) so the two panels read as
  // sibling surfaces rather than two different designs.
  const scheduledPanel = document.createElement('div');
  scheduledPanel.dataset.sidebarPanel = 'scheduled';
  // `flex: 3` matches the unscheduled catalog panel's flex in the component's
  // sidebar layout, so the Inspector below it gets the identical share of the
  // sidebar on both tabs.
  scheduledPanel.style.cssText = 'display: none; flex: 3; min-height: 0; flex-direction: column;';

  let scheduledSearchQuery = readScheduledSearch();
  let scheduledGroupBy: MatchUpCatalogGroupBy = readScheduledGroupBy();
  let scheduledFilters: CatalogFilters = readScheduledFilters();
  let scheduledFilterTip: Instance | undefined;
  const scheduledCollapsedGroups = new Set<string>();

  // Header (title row with filter icon on the right, then a meta row below).
  // Mirrors the unscheduled catalog's `sp-panel-header > spl-catalog-title-row`
  // structure so the visual treatment matches without redeclaring styles.
  const scheduledHeader = document.createElement('div');
  scheduledHeader.className = 'sp-panel-header';
  const scheduledTitleRow = document.createElement('div');
  scheduledTitleRow.className = 'spl-catalog-title-row';
  const scheduledTitle = document.createElement('div');
  scheduledTitle.className = 'sp-panel-title';
  scheduledTitle.textContent = t('schedule.scheduledTitle');

  const scheduledFilterBtn = document.createElement('button');
  scheduledFilterBtn.className = 'spl-catalog-filter-btn';
  scheduledFilterBtn.title = t('schedule.filterMatchUps');
  scheduledFilterBtn.innerHTML =
    '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>';

  scheduledTitleRow.appendChild(scheduledTitle);
  scheduledTitleRow.appendChild(scheduledFilterBtn);

  const scheduledMeta = document.createElement('div');
  scheduledMeta.className = 'sp-panel-meta';

  scheduledHeader.appendChild(scheduledTitleRow);
  scheduledHeader.appendChild(scheduledMeta);
  scheduledPanel.appendChild(scheduledHeader);

  // Toolbar — search + group-by select (no filter button; filter lives in the
  // header row above, matching the unscheduled catalog).
  const scheduledToolbar = document.createElement('div');
  scheduledToolbar.className = 'sp-catalog-toolbar';

  const scheduledSearchInput = document.createElement('input');
  scheduledSearchInput.type = 'text';
  scheduledSearchInput.className = 'sp-input';
  scheduledSearchInput.placeholder = t('schedule.searchScheduledMatchUps');
  scheduledSearchInput.value = scheduledSearchQuery;
  scheduledSearchInput.addEventListener('input', () => {
    scheduledSearchQuery = scheduledSearchInput.value;
    writeScheduledSearch(scheduledSearchQuery);
    updateScheduledPanel();
  });

  const scheduledSearchWrap = wrapSearchWithClear(scheduledSearchInput, () => {
    scheduledSearchInput.value = '';
    scheduledSearchQuery = '';
    writeScheduledSearch('');
    scheduledSearchInput.focus();
    updateScheduledPanel();
  });

  const scheduledGroupSelect = document.createElement('select');
  scheduledGroupSelect.className = 'sp-select';
  for (const [val, label] of [
    ['time', t('schedule.groupBy.time')],
    ['event', t('schedule.groupBy.event')],
    ['draw', t('schedule.groupBy.draw')],
    ['round', t('schedule.groupBy.round')],
    ['structure', t('schedule.groupBy.structure')],
  ] as const) {
    const opt = document.createElement('option');
    opt.value = val;
    opt.textContent = label;
    if (val === scheduledGroupBy) opt.selected = true;
    scheduledGroupSelect.appendChild(opt);
  }
  scheduledGroupSelect.addEventListener('change', () => {
    scheduledGroupBy = scheduledGroupSelect.value as MatchUpCatalogGroupBy;
    writeScheduledGroupBy(scheduledGroupBy);
    // Group identity changes when the grouping mode changes; clear the
    // collapsed-groups set so the new grouping doesn't start half-collapsed
    // based on stale keys from the previous mode.
    scheduledCollapsedGroups.clear();
    updateScheduledPanel();
  });

  scheduledToolbar.appendChild(scheduledSearchWrap);
  scheduledToolbar.appendChild(scheduledGroupSelect);
  scheduledPanel.appendChild(scheduledToolbar);

  // Cards container — re-populated each `updateScheduledPanel` call.
  const scheduledCardsContainer = document.createElement('div');
  scheduledCardsContainer.className = 'sp-catalog';
  scheduledCardsContainer.style.cssText = 'flex: 1; min-height: 0;';
  scheduledPanel.appendChild(scheduledCardsContainer);

  function isAnyScheduledFilterActive(): boolean {
    return !!(
      scheduledFilters.eventType ||
      scheduledFilters.eventName ||
      scheduledFilters.drawName ||
      scheduledFilters.gender ||
      scheduledFilters.roundName
    );
  }

  function updateScheduledFilterBadge(): void {
    scheduledFilterBtn.classList.toggle('active', isAnyScheduledFilterActive());
  }
  updateScheduledFilterBadge();

  function destroyScheduledFilterTip(): void {
    if (scheduledFilterTip) {
      scheduledFilterTip.destroy();
      scheduledFilterTip = undefined;
    }
  }

  function buildScheduledFilterPopover(): HTMLElement {
    // Build option lists from the unfiltered catalog source for the current
    // date so the popover always offers every available value — filtering
    // by one dimension shouldn't shrink the choices on the others.
    const items = getScheduledNotPlacedOnCourt().map((m) => scheduledMatchUpToCatalogItem(m));

    const container = document.createElement('div');
    container.className = 'spl-filter-popover';

    const popoverHeader = document.createElement('div');
    popoverHeader.className = 'spl-filter-header';

    const clearAll = document.createElement('button');
    clearAll.className = 'spl-filter-clear-btn';
    clearAll.textContent = t('schedule.filterClearAll');
    clearAll.addEventListener('click', (ev) => {
      ev.stopPropagation();
      scheduledFilters = {};
      writeScheduledFilters(scheduledFilters);
      updateScheduledFilterBadge();
      for (const sel of container.querySelectorAll<HTMLSelectElement>('select')) {
        sel.value = '';
        sel.classList.remove(FILTER_HIGHLIGHT_CLASS);
        const lbl = sel.previousElementSibling;
        if (lbl?.classList.contains('spl-filter-label')) lbl.classList.remove(FILTER_HIGHLIGHT_CLASS);
      }
      updateScheduledPanel();
    });
    popoverHeader.appendChild(clearAll);

    const closeBtn = document.createElement('button');
    closeBtn.className = 'spl-filter-close-btn';
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      destroyScheduledFilterTip();
    });
    popoverHeader.appendChild(closeBtn);

    container.appendChild(popoverHeader);

    const sections: Array<{ labelKey: string; key: keyof CatalogFilters; values: string[] }> = [
      {
        labelKey: 'schedule.filterAllEventTypes',
        key: 'eventType',
        values: uniqueCatalogValues(items, (m) => m.matchUpType),
      },
      {
        labelKey: 'schedule.filterAllEvents',
        key: 'eventName',
        values: uniqueCatalogValues(items, (m) => m.eventName),
      },
      { labelKey: 'schedule.filterAllFlights', key: 'drawName', values: uniqueCatalogValues(items, (m) => m.drawName) },
      { labelKey: 'schedule.filterAllGenders', key: 'gender', values: uniqueCatalogValues(items, (m) => m.gender) },
      {
        labelKey: 'schedule.filterAllRounds',
        key: 'roundName',
        values: uniqueCatalogValues(items, (m) => m.roundName),
      },
    ];

    for (const section of sections) {
      if (section.values.length < 2) continue;

      const label = document.createElement('label');
      label.className = 'spl-filter-label';
      label.textContent = t(section.labelKey);
      container.appendChild(label);

      const select = document.createElement('select');
      select.className = 'spl-filter-select';

      const allOpt = document.createElement('option');
      allOpt.value = '';
      allOpt.textContent = t(section.labelKey);
      select.appendChild(allOpt);

      for (const val of section.values) {
        const opt = document.createElement('option');
        opt.value = val;
        opt.textContent = val;
        select.appendChild(opt);
      }

      select.value = scheduledFilters[section.key] ?? '';

      const syncHighlight = () => {
        const filtering = select.value !== '';
        select.classList.toggle(FILTER_HIGHLIGHT_CLASS, filtering);
        label.classList.toggle(FILTER_HIGHLIGHT_CLASS, filtering);
      };
      syncHighlight();

      select.addEventListener('change', () => {
        scheduledFilters = { ...scheduledFilters, [section.key]: select.value || undefined };
        writeScheduledFilters(scheduledFilters);
        updateScheduledFilterBadge();
        syncHighlight();
        updateScheduledPanel();
      });

      container.appendChild(select);
    }

    // "Show completed" toggle — always rendered so the popover has at
    // least one functional control. Without it, dates where every orphan
    // is completed (e.g. the morning after a finished day whose courts
    // were cleared) produced an empty Clear All / × husk. Writes to the
    // shared store flag so this and the Unscheduled-side toggle stay in
    // lockstep — one mental model, one switch.
    const toggleRow = document.createElement('label');
    toggleRow.className = 'spl-filter-toggle';
    const showCompletedCheckbox = document.createElement('input');
    showCompletedCheckbox.type = 'checkbox';
    showCompletedCheckbox.checked = activeControl?.getStore().getState().showCompleted ?? false;
    showCompletedCheckbox.addEventListener('change', () => {
      activeControl?.getStore().setShowCompleted(showCompletedCheckbox.checked);
    });
    toggleRow.appendChild(showCompletedCheckbox);
    toggleRow.appendChild(document.createTextNode(` ${t('schedule.showCompleted')}`));
    container.appendChild(toggleRow);

    return container;
  }

  scheduledFilterBtn.addEventListener('click', () => {
    destroyScheduledFilterTip();
    scheduledFilterTip = tippy(scheduledFilterBtn, {
      content: buildScheduledFilterPopover(),
      placement: 'bottom-start',
      interactive: true,
      trigger: 'manual',
      appendTo: () => scheduledPanel,
      onClickOutside: () => destroyScheduledFilterTip(),
      theme: '',
    });
    scheduledFilterTip.show();
  });

  // The component's existing catalog content (everything after the control bar)
  // The component's existing catalog content, EXCLUDING the Inspector panel.
  // The Inspector is a sibling of the catalog in the layout's sidebar, so a naive
  // `Array.from(sidebar.children)` sweeps it into "catalog content" and hides it
  // whenever the Scheduled tab is shown — which is precisely why the Scheduled
  // view had no Inspector. It is identified by the `data-panel` hook rather than
  // by sibling order (both panels carry the same `sp-panel` class).
  const catalogContent = Array.from(sidebar.children).filter((el) => (el as HTMLElement).dataset.panel !== 'inspector');

  // Insert control bar at top
  sidebar.insertBefore(controlBar, sidebar.firstChild);
  // The Scheduled panel stands in for the catalog, so it takes the catalog's
  // slot — ABOVE the Inspector. Appending it to the sidebar instead leaves it
  // after the Inspector, which puts the Inspector at the TOP on the Scheduled
  // tab and at the BOTTOM on the Unscheduled tab: the panel jumps as soon as
  // you switch views. `insertBefore(_, null)` degrades to append if the
  // Inspector is ever absent.
  const inspectorEl = sidebar.querySelector(':scope > [data-panel="inspector"]');
  sidebar.insertBefore(scheduledPanel, inspectorEl);

  // Default sidebar tab is resolved after the scheduled-orphan helpers are
  // declared (see `resolveInitialTab` below), so we can land on "Scheduled"
  // when the selected date already has scheduled-but-unplaced matchUps.
  let activeTab: SidebarTab = readSidebarTab();

  function getScheduledNotPlacedOnCourt(): any[] {
    // Honors the shared "Show completed" store flag so a completed matchUp
    // whose court was cleared (manual unschedule or upstream sync wiping
    // courtId while preserving scheduledDate/scheduledTime) has a surface
    // to be re-assigned from — without the toggle, it had nowhere to live.
    const showCompleted = activeControl?.getStore().getState().showCompleted ?? false;
    const all = listScheduledOrphans(currentDate);
    return showCompleted ? all : all.filter((m: any) => !isCompletedStatus(m.matchUpStatus));
  }

  function updateBadge(): void {
    // Single factory pass; split into visible-count (respects the toggle)
    // and absolute-count (gates funnel visibility). The funnel is hidden
    // when there's nothing for the popover to act on even with the toggle
    // on — otherwise opening it surfaces an empty Clear All / × husk.
    const orphans = listScheduledOrphans(currentDate);
    const showCompleted = activeControl?.getStore().getState().showCompleted ?? false;
    const visibleCount = showCompleted
      ? orphans.length
      : orphans.filter((m: any) => !isCompletedStatus(m.matchUpStatus)).length;
    schedBadge.textContent = String(visibleCount);
    scheduledFilterBtn.style.display = orphans.length === 0 ? 'none' : '';
    // Unscheduled badge reflects the unfiltered eligible-for-unscheduled
    // count for the current date — same source the catalog widget meta
    // shows ("X unscheduled"), so the badge cannot drift from what the
    // catalog itself displays. Computed from `buildCatalog(currentDate)`
    // to share the same date / completed / BYE filtering with the catalog
    // body so the two stay aligned.
    const unscheduledCount = buildCatalog(currentDate).filter((item) => !item.isScheduled).length;
    unschedBadge.textContent = String(unscheduledCount);
  }

  function updateScheduledPanel(): void {
    // Hidden with the sidebar: built when it is shown again (`onSidebarShown`).
    if (!sidebarVisible) return;
    scheduledCardsContainer.innerHTML = '';
    const scheduled = getScheduledNotPlacedOnCourt();
    const items = scheduled.map((m) => scheduledMatchUpToCatalogItem(m));

    // Round-emphasis base per event — computed off the FULL items list
    // (pre-filter) so the offset assigned to a card stays stable as the
    // operator types in the search box. Shares the canonical
    // `computeBaseRoundByEvent` helper with the courthive-components
    // catalog widget on the Unscheduled side; before extraction TMX and
    // courthive-components each had their own inlined copy.
    const baseRoundByEvent = computeBaseRoundByEvent(items);

    // Same filter + group pipeline the unscheduled catalog runs. `behavior:
    // 'hide'` would normally drop items where `isScheduled === true`, but
    // `scheduledMatchUpToCatalogItem` already forces `isScheduled: false`
    // (so the card stays draggable), so behavior is a no-op here — explicit
    // 'dim' avoids the hide branch entirely.
    // showCompleted MUST be threaded through: `getScheduledNotPlacedOnCourt`
    // honors it (so completed orphans reach this step), but
    // `filterMatchUpCatalog` re-applies `isCompletedStatus` internally and
    // would drop them again if we left the default `false`.
    const showCompleted = activeControl?.getStore().getState().showCompleted ?? false;
    const filtered = filterMatchUpCatalog(items, scheduledSearchQuery, 'dim', scheduledFilters, showCompleted);

    // Match the unscheduled catalog meta line ("{N} unscheduled") on the
    // Scheduled side so the panel header carries the same shape and the
    // count reflects the active search + filter.
    scheduledMeta.textContent = t('schedule.scheduledCount', { count: filtered.length });

    if (!scheduled.length) {
      const hint = document.createElement('div');
      hint.style.cssText =
        'font-size: 0.6875rem; color: var(--sp-muted, var(--tmx-muted)); text-align: center; padding: 24px 8px;';
      hint.textContent = t('schedule.noScheduledMatchUps');
      scheduledCardsContainer.appendChild(hint);
      return;
    }

    if (!filtered.length) {
      const hint = document.createElement('div');
      hint.style.cssText =
        'font-size: 0.6875rem; color: var(--sp-muted, var(--tmx-muted)); text-align: center; padding: 24px 8px;';
      hint.textContent = t('schedule.noScheduledMatchUpsMatch');
      scheduledCardsContainer.appendChild(hint);
      return;
    }

    const groups = groupMatchUpCatalog(filtered, scheduledGroupBy);

    // This panel builds its cards directly, so it owns the same teardown the
    // component's catalog does: a hovered card about to be destroyed never fires
    // `mouseleave`, and its highlight would be stranded on the grid.
    clearRelatedHighlight();

    for (const [gk, groupItems] of groups) {
      const groupEl = document.createElement('div');
      groupEl.className = 'sp-group';

      const isCollapsed = scheduledCollapsedGroups.has(gk);

      const gh = document.createElement('div');
      gh.className = 'sp-group-header';

      const chevron = document.createElement('span');
      chevron.className = 'sp-group-chevron';
      chevron.textContent = isCollapsed ? '▶' : '▼';

      const ghLabel = document.createElement('span');
      ghLabel.textContent = `${gk} (${groupItems.length})`;

      gh.appendChild(chevron);
      gh.appendChild(ghLabel);

      gh.addEventListener('click', () => {
        if (scheduledCollapsedGroups.has(gk)) scheduledCollapsedGroups.delete(gk);
        else scheduledCollapsedGroups.add(gk);
        updateScheduledPanel();
      });

      const gb = document.createElement('div');
      gb.className = 'sp-group-body';
      if (isCollapsed) gb.style.display = 'none';

      // A collapsed group's cards are not built: each one grades readiness and rest. Expanding the
      // group re-runs this function.
      for (const item of isCollapsed ? [] : groupItems) {
        // isScheduled is forced to false so buildMatchUpCard attaches its
        // dragstart listener — these sidebar cards must be promotable onto a
        // court. The prominent time header (via the option) is what visually
        // marks them as already having a scheduledTime.
        // Round-offset is computed against the pre-filter `items` set so the
        // visual priority stays stable while the operator searches.
        const base = baseRoundByEvent.get(item.eventId);
        const roundOffset = base === undefined ? undefined : Math.max(0, item.roundNumber - base);
        // The time header is graded by the same readiness analysis the Inspector
        // shows, so a card cannot read green while the panel behind it reads red.
        // `evaluateReadiness` shares one engine pass across every card here.
        const time = item.scheduledTime ? scheduledTimeModel(evaluateReadiness(item.matchUpId)) : null;
        const card = buildMatchUpCard(
          item,
          { onClick: (m) => selectFromScheduledPanel(m.matchUpId) },
          {
            prominentTime: true,
            roundOffset,
            timeStatus: time?.status,
            timeTitle: time?.title,
            relatedMatchUpIds: (m) => relatedFor(m.matchUpId, currentDate),
            // Same hook as the catalog. The Scheduled panel builds its cards
            // directly rather than through the component's catalog, so the
            // badge has to be passed here too or it would appear on only half
            // the cards an operator looks at.
            renderExtra: (m) => renderRestBadge(m.matchUpId, currentDate),
          },
        );
        card.dataset.matchUpId = item.matchUpId;
        if (!item.scheduledTime) card.classList.add('no-time');
        if (activeControl?.getStore().getState().selectedMatchUp?.matchUpId === item.matchUpId) {
          card.classList.add('selected');
        }
        gb.appendChild(card);
      }

      groupEl.appendChild(gh);
      groupEl.appendChild(gb);
      scheduledCardsContainer.appendChild(groupEl);
    }
  }

  /**
   * Select a Scheduled-panel card into the Inspector.
   *
   * ⚠️ Resolves the item out of `state.matchUpCatalog` rather than passing the
   * card's own item. `scheduledMatchUpToCatalogItem` forces `isScheduled: false`
   * so `buildMatchUpCard` attaches its dragstart listener; handing that object to
   * the store would make the Inspector report "Scheduled: No" for a matchUp that
   * plainly is. `buildCatalog(currentDate)` includes scheduled-on-this-date
   * matchUps, so the lookup hits — and because the id IS in the catalog, the
   * store's "clear selection when it leaves the catalog" guard cannot wrongly
   * clear it either. The card's item is only a fallback.
   */
  function selectFromScheduledPanel(matchUpId: string): void {
    const store = activeControl?.getStore();
    if (!store) return;
    const resolved =
      store.getState().matchUpCatalog.find((m) => m.matchUpId === matchUpId) ??
      buildCatalog(currentDate).find((m) => m.matchUpId === matchUpId);
    // The store's emit moves the highlight (see the subscriber); no rebuild of the panel.
    if (resolved) store.selectMatchUp(resolved);
  }

  /** Move the Scheduled panel's highlight without rebuilding its cards. */
  function markScheduledSelection(selectedId: string | undefined): void {
    for (const card of scheduledCardsContainer.querySelectorAll<HTMLElement>('[data-match-up-id]')) {
      card.classList.toggle('selected', card.dataset.matchUpId === selectedId);
    }
  }

  // The default tab reflects the selected date's schedule state; the operator's
  // last *explicit* tab choice (persisted) is only the fallback. Land on
  // "Scheduled" when that date already has scheduled-but-unplaced matchUps — the
  // same set that drives the tab's "(#)" badge — so the actionable list shows
  // first. renderGridView re-runs on every date/mode change, so this is a
  // per-mount view decision and is applied without persisting (see setTab).
  function resolveInitialTab(): SidebarTab {
    return getScheduledNotPlacedOnCourt().length > 0 ? 'scheduled' : readSidebarTab();
  }

  function setTab(tab: SidebarTab, options?: { persist?: boolean }): void {
    const catalogWasShown = catalogOnScreen();
    activeTab = tab;
    sidebarTab = tab;
    // Persist only explicit operator choices, not the auto-resolved default, so
    // `readSidebarTab()` keeps meaning "the last tab the operator clicked".
    if (options?.persist !== false) writeSidebarTab(tab);
    unschedTab.style.cssText = tabStyle(tab === 'unscheduled');
    schedTab.style.cssText = tabStyle(tab === 'scheduled');

    if (tab === 'unscheduled') {
      scheduledPanel.style.display = 'none';
      for (const el of catalogContent) (el as HTMLElement).style.display = '';
      // Its cards were built without badges while it was out of sight.
      if (!catalogWasShown && catalogOnScreen()) repaintCatalog();
    } else {
      for (const el of catalogContent) (el as HTMLElement).style.display = 'none';
      // Explicit `flex` rather than `''` so the panel's flex-direction:column
      // takes effect (default `block` would stack the search bar above the
      // cards container without honoring the flex layout).
      scheduledPanel.style.display = 'flex';
      updateScheduledPanel();
    }
  }

  /** Rebuild the catalog's cards, so ones built while it was hidden get their badges. */
  function repaintCatalog(): void {
    activeControl?.setMatchUpCatalog(buildCatalog(currentDate));
  }

  onSidebarShown = () => {
    if (activeTab === 'unscheduled') repaintCatalog();
    else updateScheduledPanel();
  };

  unschedTab.addEventListener('click', () => setTab('unscheduled'));
  schedTab.addEventListener('click', () => setTab('scheduled'));

  // Drop-to-unschedule: dragging a placed matchUp onto the Scheduled tab or
  // its panel removes the court assignment. If the matchUp has a scheduled
  // time it stays in the Scheduled list; if it has no time it routes back
  // to Unscheduled. Without this, the only way to free a court was to
  // switch tabs and drop on Unscheduled.
  attachUnscheduleDropTarget(schedTab, refresh);
  attachUnscheduleDropTarget(scheduledPanel, refresh);

  // Apply the resolved default tab (Scheduled when the selected date has
  // scheduled-but-unplaced matchUps, else the operator's last explicit choice).
  // Not persisted — this is a per-mount view decision, not a preference change.
  activeTab = resolveInitialTab();
  setTab(activeTab, { persist: false });
  updateBadge();

  // Hook into refresh to update scheduled panel when visible. The badge
  // updates regardless of which tab is active so operators can see the
  // count grow after running the scheduler without switching tabs.
  // The unsubscribe is deliberately not kept: `destroyGridView` disposes the whole control
  // via `activeControl.destroy()`, which drops its subscribers with it, so there is nothing
  // for this scope to clean up. Binding the handle only to discard it is what the `void` was
  // hiding — and a bound-but-unused handle reads as an unsubscribe someone forgot to call.
  // Only a change of data rebuilds the panel. The store emits on every write, selection included,
  // and a click on a card used to rebuild every card in the panel to move one highlight.
  let renderedCatalog: unknown = activeControl?.getStore().getState().matchUpCatalog;
  let renderedShowCompleted = activeControl?.getStore().getState().showCompleted;
  activeControl?.getStore().subscribe((state) => {
    const dataChanged = state.matchUpCatalog !== renderedCatalog || state.showCompleted !== renderedShowCompleted;
    renderedCatalog = state.matchUpCatalog;
    renderedShowCompleted = state.showCompleted;
    if (dataChanged) updateBadge();
    if (activeTab !== 'scheduled' || !sidebarVisible) return;
    if (dataChanged) updateScheduledPanel();
    else markScheduledSelection(state.selectedMatchUp?.matchUpId);
  });
}

function attachUnscheduleDropTarget(el: HTMLElement, refresh: () => void): void {
  el.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer!.dropEffect = 'move';
    el.style.outline = '2px dashed var(--sp-accent-focus, #3b82f6)';
    el.style.outlineOffset = '-2px';
  });
  el.addEventListener('dragleave', () => {
    el.style.outline = '';
    el.style.outlineOffset = '';
  });
  el.addEventListener('drop', (e) => {
    e.preventDefault();
    el.style.outline = '';
    el.style.outlineOffset = '';
    const raw = e.dataTransfer?.getData('application/json');
    if (!raw) return;
    let payload: any;
    try {
      payload = JSON.parse(raw);
    } catch {
      return;
    }
    if (payload?.type !== 'GRID_MATCHUP') return;
    const matchUp = payload.matchUp;
    if (!matchUp?.matchUpId) return;
    unscheduleFromCourt(matchUp.matchUpId, matchUp.drawId ?? '', refresh);
  });
}

function unscheduleFromCourt(matchUpId: string, drawId: string, refresh: () => void): void {
  // Inspect the live matchUp to decide whether to preserve the scheduled
  // time. With a time → keep it (stays on the Scheduled tab). Without a
  // time → clear the date too (drops onto the Unscheduled tab).
  const { matchUps } = getCachedAllMatchUps();
  const matchUp = (matchUps || []).find((m: any) => m.matchUpId === matchUpId);
  const hasTime = !!matchUp?.schedule?.scheduledTime;

  const schedule: Record<string, string> = {
    courtId: '',
    venueId: '',
    courtOrder: '',
  };
  if (!hasTime) {
    schedule.scheduledDate = '';
    schedule.scheduledTime = '';
  }

  executeMethods(
    [
      {
        method: ADD_MATCHUP_SCHEDULE_ITEMS,
        params: { matchUpId, drawId, schedule, removePriorValues: true },
      },
      // Explicit unschedule — clear any prior active-strip "called" stamp.
      {
        method: SET_MATCHUP_CALLED_AT,
        params: { matchUpId, drawId, calledAt: null },
      },
    ],
    refresh,
  );
}

// Convert an "HH:mm" schedule string to total minutes; missing/invalid times
// sort to the bottom of the Scheduled tab by returning +Infinity.
function scheduledTimeToMinutes(time: string | undefined): number {
  if (!time || typeof time !== 'string') return Number.POSITIVE_INFINITY;
  const parts = time.split(':');
  if (parts.length < 2) return Number.POSITIVE_INFINITY;
  const h = Number.parseInt(parts[0], 10);
  const m = Number.parseInt(parts[1], 10);
  if (Number.isNaN(h) || Number.isNaN(m)) return Number.POSITIVE_INFINITY;
  return h * 60 + m;
}

export function destroyGridView(): void {
  if (activeStripUnsubscribe) {
    activeStripUnsubscribe();
    activeStripUnsubscribe = null;
  }
  if (catalogStateUnsubscribe) {
    catalogStateUnsubscribe();
    catalogStateUnsubscribe = null;
  }
  if (activeStripBlockTicker) {
    clearInterval(activeStripBlockTicker);
    activeStripBlockTicker = null;
  }
  activeStrip = null;
  latestStripSnapshot = null;
  if (activeControl) {
    activeControl.destroy();
    activeControl = null;
  }
  removeActionBar();
  clearStaleDrawBanner();
  pendingMethods = [];
  actionBarContainer = null;
  gridRootElement = null;
  currentRefresh = null;
  onSidebarShown = null;
  sidebarTab = null;
  // An Inspector left on screen by another surface must not dispatch into a dead
  // render; the action declines to offer itself instead.
  resetScheduleMutationControl();
}

/**
 * The sidebar was collapsed or expanded. Its panels skip their cards while it is collapsed, so
 * expanding it repaints whichever one is showing.
 */
export function setGridSidebarVisible(visible: boolean): void {
  const wasVisible = sidebarVisible;
  sidebarVisible = visible;
  if (visible && !wasVisible) onSidebarShown?.();
}

/** Toggle visibility of the one-row active courts strip via the store flag. */
export function setGridActiveStripVisible(visible: boolean): void {
  activeControl?.setActiveStripVisible(visible);
}

// Factory reportId for the Call Timing Variance report (see factory
// reportConstants.CALL_TIMING_VARIANCE_REPORT).
const CALL_TIMING_VARIANCE_REPORT = 'scheduling.callTimingVariance';

/**
 * Whether the Call Timing Variance report has anything to show: any matchUp
 * that has both a planned scheduledTime and an actual calledAt. Reuses the
 * page's already-cached matchUps — no extra factory call.
 */
function hasCallTimingData(): boolean {
  const { matchUps } = getCachedAllMatchUps() || {};
  return (matchUps || []).some((m: any) => m?.schedule?.calledAt && m?.schedule?.scheduledTime);
}

/** Deep-link straight to the Call Timing Variance report for this tournament. */
function openTimingVarianceReport(): void {
  const tournamentId = tournamentEngine.getTournament()?.tournamentRecord?.tournamentId;
  if (!tournamentId) return;
  context.router?.navigate(`/${TOURNAMENT}/${tournamentId}/${REPORTS_TAB}/${CALL_TIMING_VARIANCE_REPORT}`);
}

/** Refresh grid cells, catalog, dates, and issues from current factory state. */
export function refreshGridView(): void {
  currentRefresh?.();
}

/** Whether there are unsaved bulk scheduling changes. */
export function hasUnsavedGridChanges(): boolean {
  return bulkMode && pendingMethods.length > 0;
}

/** Number of unsaved bulk scheduling changes — for caller-side confirm copy. */
export function getUnsavedGridChangeCount(): number {
  return bulkMode ? pendingMethods.length : 0;
}

/**
 * Flip bulk mode on/off. Idempotent. When turning OFF with pending changes
 * the queue is discarded — the caller is responsible for any "are you sure"
 * confirmation prompt before invoking this (we never open a native browser
 * dialog from inside a pure state mutation). Returns the new state.
 */
export function setGridBulkMode(enabled: boolean): boolean {
  if (bulkMode === enabled) return bulkMode;
  if (!enabled && pendingMethods.length > 0) {
    discardPending();
  }
  bulkMode = enabled;
  return bulkMode;
}

export function getGridBulkMode(): boolean {
  return bulkMode;
}

const SEARCH_HIGHLIGHT_CLASS = 'sch2-search-highlight';

function ensureSearchHighlightStyle(): void {
  if (document.getElementById('sch2-search-style')) return;
  const style = document.createElement('style');
  style.id = 'sch2-search-style';
  style.textContent = `.${SEARCH_HIGHLIGHT_CLASS} { outline: 2px solid #f59e0b; outline-offset: -2px; background: rgba(245, 158, 11, 0.15) !important; }`;
  document.head.appendChild(style);
}

/**
 * The identity index, rebuilt only when the matchUps behind it are replaced.
 *
 * `getCachedAllMatchUps()` is mutation-invalidated, so a new `matchUps` array IS the
 * signal that the index is stale — keying the memo on the array's identity means a
 * keystroke costs a Map lookup rather than a walk over every matchUp in the
 * tournament, and a score entry or a drag still gets a fresh index on the next
 * search without this module subscribing to anything.
 */
let searchIndexSource: any = null;
let searchIndexCache: GridSearchIndex | null = null;

/** MatchUps the query resolves to by participant identity. Empty for a non-name query. */
function identityMatchUpIds(query: string): Set<string> {
  const { matchUps } = getCachedAllMatchUps() || {};
  if (searchIndexSource !== matchUps || !searchIndexCache) {
    searchIndexSource = matchUps;
    searchIndexCache = buildGridSearchIndex(matchUps);
  }
  return new Set(matchUpIdsForQuery(searchIndexCache, query));
}

/**
 * Highlight grid cells matching the search; scroll the first match into view.
 *
 * Two matchers, unioned, because they answer different questions and neither
 * subsumes the other:
 *
 *   - **identity** — `matchUpIdsForQuery` resolves a name to participantIds and those
 *     to matchUps. This is what finds a player in DOUBLES: the cell displays the pair
 *     participant's name, which the factory composes from family names alone, so
 *     "Aiden Phoebus" is not in that cell's text and never can be. Clicking his rest
 *     row used to highlight his singles and silently miss his doubles;
 *   - **text** — `cellSearchText`, unchanged. Cells render an event name, a round
 *     label, an umpire, a score and a court annotation, none of which is in the index.
 *     Replacing the text walk would have fixed doubles and broken "find the cell with
 *     the umpire I need to move".
 *
 * So identity only ever ADDS cells, which is also what makes it safe for the index to
 * fold diacritics when the text path does not.
 */
export function searchGridCells(text: string): void {
  if (!gridRootElement) return;
  ensureSearchHighlightStyle();

  // Remove previous highlights
  const prev = gridRootElement.querySelectorAll(`.${SEARCH_HIGHLIGHT_CLASS}`);
  for (const el of prev) el.classList.remove(SEARCH_HIGHLIGHT_CLASS);

  const needle = searchNormalize(text);
  if (!needle) return;

  const identityMatches = identityMatchUpIds(text);
  const cells = gridRootElement.querySelectorAll(`[${DATA_MATCHUP_ID}]`);
  let firstMatch: HTMLElement | null = null;

  for (const cell of cells) {
    const el = cell as HTMLElement;
    const matchUpId = el.dataset.matchupId;
    const matched = (!!matchUpId && identityMatches.has(matchUpId)) || cellSearchText(el).includes(needle);
    if (matched) {
      el.classList.add(SEARCH_HIGHLIGHT_CLASS);
      firstMatch ??= el;
    }
  }

  if (firstMatch) {
    firstMatch.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' });
  }
}

// ============================================================================
// Bulk Mode — Execute / Save / Discard
// ============================================================================

let staleDrawBanner: HTMLElement | null = null;

/** Remove the "draw deleted" explanatory banner if present. */
function clearStaleDrawBanner(): void {
  if (staleDrawBanner) {
    staleDrawBanner.remove();
    staleDrawBanner = null;
  }
}

/**
 * Show a persistent inline banner explaining that some queued scheduling
 * changes could not be saved because their draw was deleted by another user.
 * Persistent (not a toast) so the director can read the reason after the fact;
 * cleared on the next grid render or on manual dismiss.
 */
function showStaleDrawBanner(droppedCount: number): void {
  if (!actionBarContainer) return;
  clearStaleDrawBanner();

  const banner = buildInlineNotice({
    intent: 'warning',
    message: t('schedule.staleDrawSaveSkipped', {
      n: droppedCount,
      defaultValue:
        '{{n}} scheduling change(s) could not be saved — their draw was deleted by another user. Any remaining changes were saved.',
    }),
    onDismiss: () => clearStaleDrawBanner(),
  });

  actionBarContainer.insertBefore(banner, actionBarContainer.firstChild);
  staleDrawBanner = banner;
}

/**
 * Execute mutation methods — immediate or bulk.
 * In immediate mode: sends via mutationRequest (server + local).
 * In bulk mode: runs locally on competitionEngine, queues for batch send.
 */
function executeMethods(methods: any[], onRefresh: () => void): void {
  // Plan mode: a drop edits the SCENARIO, never the official schedule. Fold the
  // drop's methods into the scenario's placements and persist via
  // updateScheduleScenario (which touches scheduling.scenarios, not matchUps);
  // the re-render re-projects the plan. Engine matchUp state is never mutated.
  if (planContext) {
    const { scenarioId, tournamentId } = planContext;
    const current = listScheduleScenarios(tournamentId).find((s: any) => s.scenarioId === scenarioId);
    const placements = foldMethodsIntoScenario(current?.placements ?? [], methods, tournamentId);
    void updateScheduleScenario(tournamentId, scenarioId, { placements }).then((result: any) => {
      if (result?.error) {
        scheduleToast({ message: t('schedule.plan.updateFailed'), intent: INTENT_DANGER });
        return;
      }
      onRefresh();
    });
    return;
  }
  if (!bulkMode) {
    // A draw may have been deleted by another client between render and this
    // drop. Sending a schedule method for a now-missing draw errors
    // server-side ("Missing drawDefinition"); detect it here and refresh
    // instead — the refresh re-derives the grid so the orphaned matchUp drops.
    if (batchReferencesMissingDraw(methods, getExistingDrawIds())) {
      scheduleToast({
        message: t('schedule.drawRemovedRefreshing', {
          defaultValue: "That match's draw was just removed by another change — refreshing",
        }),
        intent: INTENT_WARNING,
      });
      invalidateMatchUpCaches();
      onRefresh();
      return;
    }
    mutationRequest({
      methods,
      engine: COMPETITION_ENGINE,
      callback: (result: any) => {
        if (!result.success) console.error('[schedule2] mutation error', result);
        // Factory state just changed — drop matchUp caches so the refresh
        // re-fetches against the new truth. dateRange/tournamentInfo are
        // page-scoped and survive mutations.
        invalidateMatchUpCaches();
        onRefresh();
      },
    });
    return;
  }

  // Bulk mode: execute locally for visual feedback
  const directives = tools.makeDeepCopy(methods);
  const result = competitionEngine.executionQueue(directives, true);
  if (result?.error) {
    console.error('[schedule2] local execution error', result);
    scheduleToast({ message: t('gridView.localFailed'), intent: INTENT_DANGER });
    return;
  }

  // Queue methods for batch server send
  pendingMethods.push(methods);
  // Bulk mode runs the mutation locally, so the cached matchUp data is
  // already stale relative to the engine — invalidate before the refresh
  // pulls fresh data.
  invalidateMatchUpCaches();
  onRefresh();
  updateActionBar();
}

/** Save all pending bulk changes to server. */
async function savePending(): Promise<void> {
  if (!pendingMethods.length) return;

  // Guard at submission: a draw may have been deleted by another client since
  // these changes were queued. Submitting a schedule method for a missing draw
  // errors server-side with an opaque "Missing drawDefinition"; instead drop
  // those whole batches (keeping a swap's interdependent methods atomic), send
  // only the valid ones, and tell the user which changes could not be saved
  // and why. The remote-deletion broadcast already pruned the orphaned
  // matchUps from local state, so no extra re-render is needed here.
  const { valid, stale } = partitionBatchesByDrawExistence(pendingMethods, getExistingDrawIds());
  pendingMethods = [];

  if (stale.length) {
    showStaleDrawBanner(stale.length);
    invalidateMatchUpCaches();
  }

  const allMethods = valid.flat();
  if (!allMethods.length) {
    // Everything queued referenced a deleted draw — nothing to send.
    updateActionBar();
    return;
  }

  mutationRequest({
    methods: allMethods,
    engine: COMPETITION_ENGINE,
    callback: (result: any) => {
      if (result?.success || !result?.error) {
        scheduleToast({ message: `Saved ${allMethods.length} scheduling changes`, intent: INTENT_SUCCESS });
      } else {
        console.error('[schedule2] bulk save error', result);
        scheduleToast({ message: t('gridView.serverFailed'), intent: INTENT_DANGER });
      }
      updateActionBar();
    },
  });

  updateActionBar();
}

/** Discard pending changes by reloading factory state from IndexedDB. */
async function discardPending(): Promise<void> {
  if (!pendingMethods.length) {
    pendingMethods = [];
    updateActionBar();
    return;
  }

  const tournamentId = getCachedTournamentInfo()?.tournamentInfo?.tournamentId;
  if (!tournamentId) return;

  try {
    const record = await tmx2db.findTournament(tournamentId);
    if (record) {
      competitionEngine.setState(record);
      // setState rewrote the engine's tournament store underneath the
      // cache — drop matchUp caches so the re-render reads fresh data.
      invalidateMatchUpCaches();
    }
  } catch (err) {
    console.error('[schedule2] failed to reload from IndexedDB', err);
  }

  pendingMethods = [];
  scheduleToast({ message: t('gridView.discarded'), intent: INTENT_WARNING });
  updateActionBar();

  // Re-render the grid view to reflect restored state
  if (activeControl && actionBarContainer) {
    const container = actionBarContainer;
    const date = currentDate;
    destroyGridView();
    renderGridView(container, date);
  }
}

// ============================================================================
// Action Bar (floating save/discard bar for bulk mode)
// ============================================================================

function updateActionBar(): void {
  if (!bulkMode || !pendingMethods.length) {
    removeActionBar();
    return;
  }
  if (!actionBarContainer) return;

  if (!actionBar) {
    actionBar = document.createElement('div');
    actionBar.style.cssText = [
      POSITION_STICKY,
      'bottom: 0',
      'z-index: 10',
      DISPLAY_FLEX,
      'align-items: center',
      'gap: 12px',
      'padding: 10px 16px',
      'background: var(--sp-panel-bg, var(--tmx-bg-primary))',
      'border-top: 2px solid var(--sp-accent, var(--tmx-accent-blue))',
      'box-shadow: 0 -2px 8px rgba(0,0,0,0.1)',
    ].join('; ');
    actionBarContainer.appendChild(actionBar);
  }

  const count = pendingMethods.length;
  const totalMethods = pendingMethods.flat().length;

  actionBar.innerHTML = '';

  // Save button
  const saveBtn = document.createElement('button');
  saveBtn.className = 'sp-btn sp-btn--success';
  saveBtn.innerHTML = `<i class="fa-solid fa-cloud-arrow-up" style="margin-right:6px;"></i>Save ${totalMethods} change${totalMethods === 1 ? '' : 's'}`;
  saveBtn.addEventListener('click', () => savePending());
  actionBar.appendChild(saveBtn);

  // Discard button
  const discardBtn = document.createElement('button');
  discardBtn.className = 'sp-btn sp-btn--danger';
  discardBtn.innerHTML = '<i class="fa-solid fa-rotate-left" style="margin-right:6px;"></i>Discard';
  discardBtn.addEventListener('click', () => discardPending());
  actionBar.appendChild(discardBtn);

  // Status text
  const status = document.createElement('span');
  status.style.cssText = 'font-size: 0.75rem; color: var(--sp-warn-text, var(--tmx-accent-orange, #f59e0b));';
  status.textContent = `${count} unsaved action${count === 1 ? '' : 's'} — changes are local only`;
  actionBar.appendChild(status);
}

function removeActionBar(): void {
  if (actionBar) {
    actionBar.remove();
    actionBar = null;
  }
}

// ============================================================================
// Interactive Court Grid (with drag/drop + data attributes)
// ============================================================================

interface InteractiveGrid {
  element: HTMLElement;
  rebuild: (date: string) => void;
}

interface GridCallbacks {
  onRefresh: () => void;
  executeMethods: (methods: any[], onRefresh: () => void) => void;
}

/**
 * Mark a grid cell whose placement a director has pinned. Extracted from the
 * cell builder to keep that function under the cognitive-complexity ceiling.
 */
function applyScheduleLockDecoration(cellContent: HTMLElement, cellData: any): void {
  if (!isScheduleLocked(cellData)) return;
  cellContent.classList.add('tmx-schedule-locked-cell');
  const reason = scheduleLockReason(cellData);
  cellContent.title = reason ? t('schedule.lockedWithReason', { reason }) : t('schedule.lockedTip');
}

function buildRowCourtCells(params: {
  grid: HTMLElement;
  row: any;
  ri: number;
  visibleCourts: { court: any; originalIndex: number }[];
  courtPrefix: string;
  emptyCellStyle: string;
  allRows: any[];
  callbacks: GridCallbacks;
}): void {
  const { grid, row, ri, visibleCourts, courtPrefix, emptyCellStyle, allRows, callbacks } = params;
  for (const visibleCourt of visibleCourts) {
    if (!row) {
      const emptyCell = document.createElement('div');
      emptyCell.style.cssText = emptyCellStyle;
      grid.appendChild(emptyCell);
      continue;
    }

    const cellKey = `${courtPrefix}${visibleCourt.originalIndex}`;
    const cellData = row[cellKey];

    const courtInfo = visibleCourt.court;
    const courtId = cellData?.schedule?.courtId ?? courtInfo?.courtId ?? '';
    const venueId = cellData?.schedule?.venueId ?? courtInfo?.venueId ?? '';
    const courtOrder = cellData?.schedule?.courtOrder ?? ri + 1;

    // Reserved cells (another facility-sharing tournament's occupancy) are opaque + read-only: build
    // them directly (bypass the matchUp mapper) and carry no matchUpId, so no drag source is attached.
    const cellContent = cellData?.isReserved
      ? buildScheduleGridCell(
          { matchUpId: '', isReserved: true, reservation: cellData.reservation, schedule: cellData.schedule },
          DEFAULT_SCHEDULE_CELL_CONFIG,
        )
      : buildScheduleGridCell(mapMatchUpToCellData(cellData || {}), DEFAULT_SCHEDULE_CELL_CONFIG);

    const cell = document.createElement('div');
    cell.style.cssText = 'min-height: 60px; font-size: 0.6875rem;';
    cell.setAttribute(DATA_COURT_ID, courtId);
    cell.setAttribute(DATA_VENUE_ID, venueId);
    cell.setAttribute(DATA_COURT_ORDER, String(courtOrder));

    const matchUpId = cellContent.getAttribute(DATA_MATCHUP_ID);
    const drawId = cellContent.getAttribute(DATA_DRAW_ID);
    // Plan mode: tint cells the scenario relocates so "planned" reads distinctly
    // from "official" placements sharing the grid.
    if (matchUpId && plannedMatchUpIdSet.has(matchUpId)) cellContent.classList.add('tmx-planned-cell');
    // Completed matchUps can't be re-planned — mark them locked in Plan mode.
    if (planContext && matchUpId && (cellData?.winningSide || isCompletedStatus(cellData?.matchUpStatus))) {
      cellContent.classList.add('tmx-plan-locked-cell');
      cellContent.title = t('schedule.plan.completedLocked');
    }
    // Plan double-books this court slot — warn before commit.
    if (planContext && matchUpId && plannedConflictMatchUpIdSet.has(matchUpId)) {
      cellContent.classList.add('tmx-plan-conflict-cell');
      cellContent.title = t('schedule.plan.conflictTip');
    }
    // A director's schedule lock — survives Clear and re-scheduling.
    if (matchUpId) applyScheduleLockDecoration(cellContent, cellData);
    if (matchUpId) cell.setAttribute(DATA_MATCHUP_ID, matchUpId);
    if (drawId) cell.setAttribute(DATA_DRAW_ID, drawId);
    // The occupant's own scheduledTime — read by the swap path so the two
    // matchUps trade times along with court/order (a true positional swap).
    if (matchUpId && cellData?.schedule?.scheduledTime) {
      cell.setAttribute(DATA_SCHEDULED_TIME, cellData.schedule.scheduledTime);
    }

    cell.appendChild(cellContent);

    if (cellData?.matchUpId) {
      attachCellDragSource(cell, cellData);
    }

    if (!cellData?.isBlocked) {
      attachCellDropTarget(cell);
    }

    cell.addEventListener('click', (e: MouseEvent) => {
      if (cell.draggable && cell.style.opacity === '0.4') return;

      handleSchedule2CellClick(e, {
        cellData,
        courtId,
        venueId,
        courtOrder,
        scheduledDate: currentDate,
        allRows,
        courtPrefix,
        rowIndex: ri,
        onRefresh: callbacks.onRefresh,
        executeMethods: callbacks.executeMethods,
        matchUpListProvider: () => getFilteredMatchUpList(currentDate, activeControl),
        findCatalogItem: (mid: string) => buildCatalog(currentDate).find((m) => m.matchUpId === mid),
      });
    });
    cell.style.cursor = cell.draggable ? 'grab' : 'pointer';

    grid.appendChild(cell);
  }
}

function getFilteredMatchUpList(date: string, control: SchedulePageControl | null): { label: string; value: string }[] {
  const catalog = buildCatalog(date);
  const storeState = control?.getStore().getState();
  const filters = storeState?.catalogFilters;
  const showCompleted = storeState?.showCompleted ?? false;
  return catalog
    .filter(
      (m) =>
        !m.isScheduled &&
        (m.sides?.length ?? 0) >= 1 &&
        (showCompleted || !isCompletedStatus(m.matchUpStatus)) &&
        (!filters?.eventType || m.matchUpType === filters.eventType) &&
        (!filters?.eventName || m.eventName === filters.eventName) &&
        (!filters?.drawName || (m.drawName ?? m.drawId) === filters.drawName) &&
        (!filters?.gender || m.gender === filters.gender) &&
        (!filters?.roundName || m.roundName === filters.roundName),
    )
    .map((m) => ({
      label: `${m.eventName} ${m.roundName || ''} — ${matchUpLabel(m)}`.trim(),
      value: m.matchUpId,
    }));
}

function attachCellDragSource(cell: HTMLElement, cellData: any): void {
  cell.draggable = true;
  cell.title = `${cellData.eventName || ''} ${cellData.roundName || ''}`.trim();

  cell.addEventListener('dragstart', (e) => {
    e.dataTransfer!.setData(
      'application/json',
      JSON.stringify({
        type: 'GRID_MATCHUP',
        matchUp: {
          matchUpId: cellData.matchUpId,
          drawId: cellData.drawId,
          eventId: cellData.eventId,
          eventName: cellData.eventName,
          roundName: cellData.roundName,
          matchUpType: cellData.matchUpType,
          sides: (cellData.sides || []).map((s: any) => ({
            participantName: s.participant?.participantName ?? s.participantName,
            participantId: s.participantId ?? s.participant?.participantId,
          })),
        },
        // The dragged matchUp's origin slot. When it's dropped onto an occupied
        // grid cell, the occupant is relocated here — a true swap. Without this
        // the displaced matchUp would have nowhere to go and fall off the grid.
        source: {
          courtId: cellData.schedule?.courtId,
          venueId: cellData.schedule?.venueId,
          courtOrder: cellData.schedule?.courtOrder,
          scheduledTime: cellData.schedule?.scheduledTime,
          scheduledDate: cellData.schedule?.scheduledDate,
        },
      }),
    );
    // Marker so the Now-strip dragover affordance can detect a grid-sourced
    // drag without reading the (drag-protected) payload mid-drag.
    e.dataTransfer!.setData(GRID_DRAG_MARKER, '1');
    e.dataTransfer!.effectAllowed = 'move';
    cell.style.opacity = '0.4';
  });
  cell.addEventListener('dragend', () => {
    cell.style.opacity = '';
  });
}

function attachCellDropTarget(cell: HTMLElement): void {
  cell.addEventListener('dragover', (e) => {
    e.preventDefault();
    cell.style.outline = '2px solid var(--sp-accent-focus, #3b82f6)';
    cell.style.outlineOffset = '-2px';
    e.dataTransfer!.dropEffect = 'move';
  });
  cell.addEventListener('dragleave', () => {
    cell.style.outline = '';
    cell.style.outlineOffset = '';
  });
  cell.addEventListener('drop', (e) => {
    e.preventDefault();
    cell.style.outline = '';
    cell.style.outlineOffset = '';
  });
}

// ============================================================================
// Court Visibility
// ============================================================================

function getCourtMatchUpCounts(rows: any[], courtsData: any[], courtPrefix: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const court of courtsData) counts.set(court.courtId, 0);
  for (const row of rows) {
    for (let ci = 0; ci < courtsData.length; ci++) {
      const cellData = row[`${courtPrefix}${ci}`];
      if (cellData?.matchUpId) {
        const courtId = courtsData[ci].courtId;
        counts.set(courtId, (counts.get(courtId) ?? 0) + 1);
      }
    }
  }
  return counts;
}

function destroyVisibilityTip(): void {
  if (visibilityTip) {
    visibilityTip.destroy();
    visibilityTip = null;
  }
}

function buildVisibilityPopover(
  allCourtsData: any[],
  matchUpCounts: Map<string, number>,
  onChanged: () => void,
): HTMLElement {
  const pop = document.createElement('div');
  pop.style.cssText =
    'padding: 10px; min-width: 220px; max-width: 300px; font-family: ui-sans-serif, system-ui, sans-serif; font-size: 0.75rem;';

  // quick actions
  const actions = document.createElement('div');
  actions.style.cssText = DISPLAY_FLEX + '; gap: 6px; margin-bottom: 8px;';

  const showAllBtn = document.createElement('button');
  showAllBtn.className = 'button font-medium';
  showAllBtn.style.cssText = 'font-size: 0.6875rem; padding: 2px 8px; border-radius: 4px; cursor: pointer;';
  showAllBtn.textContent = t('schedule.showAll');
  showAllBtn.addEventListener('click', () => {
    hiddenCourtIds.clear();
    destroyVisibilityTip();
    onChanged();
  });

  const hideEmptyBtn = document.createElement('button');
  hideEmptyBtn.className = 'button font-medium';
  hideEmptyBtn.style.cssText = 'font-size: 0.6875rem; padding: 2px 8px; border-radius: 4px; cursor: pointer;';
  hideEmptyBtn.textContent = t('schedule.hideEmpty');
  hideEmptyBtn.addEventListener('click', () => {
    for (const court of allCourtsData) {
      if ((matchUpCounts.get(court.courtId) ?? 0) === 0) {
        hiddenCourtIds.add(court.courtId);
      }
    }
    destroyVisibilityTip();
    onChanged();
  });

  actions.appendChild(showAllBtn);
  actions.appendChild(hideEmptyBtn);
  pop.appendChild(actions);

  // court list grouped by venue
  const venueMap = new Map<string, any[]>();
  for (const court of allCourtsData) {
    const key = court.venueName || court.venueId || '';
    if (!venueMap.has(key)) venueMap.set(key, []);
    venueMap.get(key)!.push(court);
  }

  for (const [venueName, courts] of venueMap) {
    if (venueMap.size > 1) {
      const venueLabel = document.createElement('div');
      venueLabel.style.cssText =
        'font-size: 0.5625rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: var(--sp-muted, #9ca3af); margin: 6px 0 2px;';
      venueLabel.textContent = venueName;
      pop.appendChild(venueLabel);
    }

    for (const court of courts) {
      const count = matchUpCounts.get(court.courtId) ?? 0;
      const isHidden = hiddenCourtIds.has(court.courtId);

      const row = document.createElement('label');
      row.style.cssText =
        DISPLAY_FLEX +
        '; align-items: center; gap: 6px; padding: 3px 0; cursor: pointer;' +
        (count === 0 ? ' opacity: 0.5;' : '');

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = !isHidden;
      checkbox.style.cssText = 'cursor: pointer; accent-color: var(--tmx-accent-blue, #3b82f6);';
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) {
          hiddenCourtIds.delete(court.courtId);
        } else {
          hiddenCourtIds.add(court.courtId);
        }
        destroyVisibilityTip();
        onChanged();
      });

      const name = document.createElement('span');
      name.style.cssText = 'flex: 1;';
      name.textContent = court.courtName || court.courtId;

      const badge = document.createElement('span');
      badge.style.cssText = 'font-size: 0.625rem; color: var(--sp-muted, #9ca3af);';
      badge.textContent = count > 0 ? `${count}` : t('schedule.empty');

      row.appendChild(checkbox);
      row.appendChild(name);
      row.appendChild(badge);
      pop.appendChild(row);
    }
  }

  return pop;
}

function buildGridHeaders(params: {
  grid: HTMLElement;
  stickyHeader: string;
  courtsData: any[];
  courtCount: number;
  emptyCount: number;
  handleAddVenue: () => void;
  allCourtsData?: any[];
  matchUpCounts?: Map<string, number>;
  onVisibilityChanged?: () => void;
  scheduledDate?: string;
}): HTMLElement[] {
  const {
    grid,
    stickyHeader,
    courtsData,
    courtCount,
    emptyCount,
    handleAddVenue,
    allCourtsData,
    matchUpCounts,
    onVisibilityChanged,
    scheduledDate,
  } = params;
  const corner = document.createElement('div');
  corner.style.cssText =
    stickyHeader +
    '; left: 0; z-index: 3; color: var(--sp-muted); cursor: pointer;' +
    DISPLAY_FLEX +
    '; align-items: center; justify-content: center; gap: 4px;';

  const eyeIcon = document.createElement('i');
  eyeIcon.className = hiddenCourtIds.size > 0 ? 'fa-solid fa-eye-slash' : 'fa-solid fa-eye';
  eyeIcon.style.cssText = 'font-size: 0.75rem;';
  corner.appendChild(eyeIcon);

  if (hiddenCourtIds.size > 0) {
    const badge = document.createElement('span');
    badge.style.cssText =
      'font-size: 0.5625rem; font-weight: 700; background: var(--tmx-fill-accent, #2563eb); color: #fff; border-radius: 50%; min-width: 14px; height: 14px; display: inline-flex; align-items: center; justify-content: center;';
    badge.textContent = String(hiddenCourtIds.size);
    corner.appendChild(badge);
  }

  if (allCourtsData && matchUpCounts && onVisibilityChanged) {
    corner.addEventListener('click', () => {
      destroyVisibilityTip();
      const content = buildVisibilityPopover(allCourtsData, matchUpCounts, onVisibilityChanged);
      visibilityTip = tippy(corner, {
        content,
        theme: 'light-border',
        trigger: 'manual',
        interactive: true,
        placement: 'bottom-start',
        appendTo: () => document.body,
      });
      visibilityTip.show();
    });
  }

  grid.appendChild(corner);

  const courtHeaders: HTMLElement[] = [];
  const showCourtIdentifiers = () => scheduleConfig.get().court_identifiers !== false;
  for (let ci = 0; ci < courtCount; ci++) {
    const court = courtsData[ci];
    const courtName = court.courtName || `Court ${ci + 1}`;
    const th = document.createElement('div');
    th.style.cssText = stickyHeader + '; cursor: pointer;';
    th.title = courtName;
    th.textContent = showCourtIdentifiers() ? courtName : '';
    th.addEventListener('click', (e: MouseEvent) => {
      e.stopPropagation();
      const visible = showCourtIdentifiers();
      const addremove = visible ? t('remove') : t('add');
      const courtInfo = { courtId: court.courtId, courtName };
      const columnShim = {
        updateDefinition: ({ title }: { title: string }) => {
          th.textContent = showCourtIdentifiers() ? title : '';
          th.title = title;
        },
      };
      tipster({
        target: e.currentTarget as HTMLElement,
        options: [
          {
            option: `${addremove} ${t('settings.courtidentifiers')}`,
            onClick: () => {
              scheduleConfig.set({ court_identifiers: !visible });
              const showing = showCourtIdentifiers();
              for (let i = 0; i < courtHeaders.length; i++) {
                const c = courtsData[i];
                const name = c?.courtName || `Court ${i + 1}`;
                courtHeaders[i].textContent = showing ? name : '';
              }
            },
          },
          {
            option: t('rename'),
            onClick: () => renameCourt({ column: columnShim, courtInfo }),
          },
          {
            option: 'Print court card(s)',
            onClick: () => printCourtMatchUpCards({ courtId: court.courtId, courtName, scheduledDate }),
          },
        ],
      });
    });
    courtHeaders.push(th);
    grid.appendChild(th);
  }

  for (let ei = 0; ei < emptyCount; ei++) {
    const th = document.createElement('div');
    th.style.cssText = stickyHeader + '; opacity: 0.6;';
    if (ei === 0) {
      const addVenueLabel = t('pages.venues.addVenue.title');
      if (courtCount === 0) {
        th.innerHTML = `<button style="font-size: 0.6875rem; font-weight: 600; padding: 3px 10px; border-radius: 6px; border: 1px solid var(--tmx-accent-blue, #3b82f6); background: var(--tmx-bg-primary, #fff); color: var(--tmx-accent-blue, #3b82f6); cursor: pointer;">${addVenueLabel}</button>`;
      } else {
        th.innerHTML = `<span style="font-weight: normal; color: var(--tmx-accent-blue, #3b82f6); cursor: pointer;">${addVenueLabel}</span>`;
      }
      th.style.cursor = 'pointer';
      th.addEventListener('click', (e) => {
        e.stopPropagation();
        handleAddVenue();
      });
    }
    grid.appendChild(th);
  }

  return courtHeaders;
}

function buildInteractiveGrid(selectedDate: string, callbacks: GridCallbacks): InteractiveGrid {
  const TIME_COL_WIDTH = GRID_TIME_COL_WIDTH_PX;
  const MIN_PLACEHOLDER_ROWS = 8;

  const root = document.createElement('div');
  root.style.cssText = 'width: 100%; height: 100%; overflow: auto;';
  gridRootElement = root;

  const handleAddVenue = () => {
    addVenue((result: any) => {
      if (result?.success) {
        // addVenue bypasses our executeMethods invalidation hook — the
        // new court column would never appear on refresh without an
        // explicit cache drop here (Journey 41 caught this).
        invalidateMatchUpCaches();
        // Refresh in place via the grid's own rebuild path (matches every
        // other mutation in this file). A full tab re-render tore down the
        // entire tab and short-circuited back to a router navigate when
        // currentDate happened to be empty, so the new venue's column would
        // silently fail to appear.
        callbacks.onRefresh();
      }
    }, COMPETITION_ENGINE);
  };

  function render(date: string): void {
    root.innerHTML = '';

    // Tournament-level minCourtGridRows extension wins over the hardcoded
    // default so all directors editing the tournament see the same grid
    // density once anyone has nudged the Rows stepper in the header.
    const extensionMinRows = readScheduleDisplayConfig().minCourtGridRows;
    const minCourtGridRows = extensionMinRows ?? DEFAULT_MIN_COURT_GRID_ROWS;
    const MIN_COURT_WIDTH = readUserMinCourtWidth();
    const scheduleResult = getScheduleGridData(date, { minCourtGridRows });

    // Shallow-clone each row so the reserved-cell injection below never mutates the CACHED schedule
    // rows. Without this, a prior render's reserved cell lingers in the cache and ghosts alongside the
    // new one when the projection changes under live refresh (a peer reschedules to a different slot).
    const rows: any[] = (scheduleResult.rows || []).map((row: any) => ({ ...row }));
    const allCourtsData: any[] = scheduleResult.courtsData || [];
    const courtPrefix: string = scheduleResult.courtPrefix || 'C|';

    // Overlay read-only reserved cells (other facility-sharing tournaments' court occupancy) into the
    // empty slots of the owned grid. Data is a slim projection cached by reservedCells — no records
    // are loaded. Runs before conflict annotation so a reserved slot participates in nothing else.
    const primaryTournamentId = getCachedTournamentInfo()?.tournamentInfo?.tournamentId ?? '';
    mergeReservedCellsIntoRows(rows, getReservedCellsForDate(date, primaryTournamentId), allCourtsData, courtPrefix);

    // Run proConflicts and annotate cell data with issue styling info
    if (allCourtsData.length) annotateConflicts(rows, allCourtsData, courtPrefix);

    // Court visibility: compute matchUp counts, then filter to visible courts
    const matchUpCounts = getCourtMatchUpCounts(rows, allCourtsData, courtPrefix);

    // Prune hiddenCourtIds of courts that no longer exist
    for (const id of hiddenCourtIds) {
      if (!allCourtsData.some((c) => c.courtId === id)) hiddenCourtIds.delete(id);
    }

    // Build visible courts with mapping to original indices (for cell data lookup)
    const visibleCourts: { court: any; originalIndex: number }[] = [];
    for (let i = 0; i < allCourtsData.length; i++) {
      if (!hiddenCourtIds.has(allCourtsData[i].courtId)) {
        visibleCourts.push({ court: allCourtsData[i], originalIndex: i });
      }
    }
    const courtsData = visibleCourts.map((vc) => vc.court);
    const courtCount = courtsData.length;

    // Calculate placeholder columns to fill remaining space (always at least 1 for "Add venue")
    const emptyCalc = MINIMUM_SCHEDULE_COLUMNS - courtCount;
    const emptyCount = emptyCalc <= 0 ? 1 : emptyCalc;
    const totalColumns = courtCount + emptyCount;

    // Ensure we have enough rows to display even when no courts
    const displayRows = rows.length || MIN_PLACEHOLDER_ROWS;

    const grid = document.createElement('div');
    grid.style.cssText = [
      'display: grid',
      'gap: 1px',
      'background: var(--sp-line, #e5e7eb)',
      `min-width: ${TIME_COL_WIDTH + totalColumns * MIN_COURT_WIDTH}px`,
      `grid-template-columns: ${TIME_COL_WIDTH}px repeat(${totalColumns}, minmax(${MIN_COURT_WIDTH}px, 1fr))`,
    ].join('; ');

    const STICKY_HEADER = [
      POSITION_STICKY,
      // top tracks the sticky strip above (set on the scroll wrapper). When
      // the strip is hidden the var resolves to 0px so headers stick to the
      // viewport top.
      'top: var(--strip-offset, 0px)',
      'z-index: 2',
      'background: var(--sp-panel-bg, #fff)',
      'padding: 6px 4px',
      FONT_SIZE_11,
      'font-weight: 700',
      'text-align: center',
      'white-space: nowrap',
      'overflow: hidden',
      'text-overflow: ellipsis',
    ].join('; ');

    const STICKY_ROW = [
      POSITION_STICKY,
      'left: 0',
      'z-index: 1',
      'background: var(--sp-panel-bg, #fff)',
      'padding: 6px 4px',
      FONT_SIZE_11,
      'font-weight: 600',
      'color: var(--sp-muted, #888)',
      DISPLAY_FLEX,
      'align-items: center',
      'justify-content: center',
    ].join('; ');

    const EMPTY_CELL = 'min-height: 60px; background: var(--sp-panel-bg, #fff); opacity: 0.4;';

    const onVisibilityChanged = () => {
      destroyVisibilityTip();
      render(date);
      refreshActiveStrip(date);
    };
    const courtHeaders = buildGridHeaders({
      grid,
      stickyHeader: STICKY_HEADER,
      courtsData,
      courtCount,
      emptyCount,
      handleAddVenue,
      allCourtsData,
      matchUpCounts,
      onVisibilityChanged,
      scheduledDate: date,
    });

    // ── Data rows ──

    const rowLabels: HTMLElement[] = [];
    for (let ri = 0; ri < displayRows; ri++) {
      const row = ri < rows.length ? rows[ri] : null;

      const rowCell = document.createElement('div');
      rowCell.style.cssText = STICKY_ROW + (row ? '; cursor: pointer;' : '');
      rowCell.textContent = String(ri + 1);
      if (row) {
        rowCell.addEventListener('click', (e: MouseEvent) => {
          handleSchedule2RowClick(e, {
            executeMethods: callbacks.executeMethods,
            onRefresh: callbacks.onRefresh,
            rowData: row,
            courtPrefix,
            courtsData,
          });
        });
      }
      rowLabels.push(rowCell);
      grid.appendChild(rowCell);

      buildRowCourtCells({
        grid,
        row,
        ri,
        visibleCourts,
        courtPrefix,
        emptyCellStyle: EMPTY_CELL,
        allRows: rows,
        callbacks,
      });

      // Placeholder cells for empty columns
      for (let ei = 0; ei < emptyCount; ei++) {
        const emptyCell = document.createElement('div');
        emptyCell.style.cssText = EMPTY_CELL;
        grid.appendChild(emptyCell);
      }
    }

    // ── Apply issue indicators to court headers and row labels ──
    // Use allTournamentMatchUps-based proConflicts (annotateConflicts' cell data misses some conflict types)
    applyHeaderRowIssueIndicators(courtHeaders, rowLabels, courtsData, date);

    root.appendChild(grid);
  }

  // Initial render
  render(selectedDate);

  return {
    element: root,
    rebuild: (date: string) => render(date),
  };
}

// ============================================================================
// Factory Data Helpers
// ============================================================================

/** Pull side participant IDs out of a factory matchUp (handles team/individual nesting). */
function extractParticipantIds(matchUp: any): string[] {
  const ids: string[] = [];
  for (const side of matchUp?.sides ?? []) {
    const participant = side.participant;
    if (!participant) {
      const sideId = side.participantId;
      if (sideId) ids.push(sideId);
      continue;
    }
    if (participant.individualParticipantIds?.length) {
      // Single variadic push rather than one per id — SonarJS flags repeated
      // `Array#push()` at the same scope.
      ids.push(...participant.individualParticipantIds);
    } else if (participant.participantId) {
      ids.push(participant.participantId);
    }
  }
  return ids;
}

/**
 * The day's non-SCHEDULED availability blocks, loaded once.
 *
 * Building an `AvailabilityEngine` costs an `init(tournamentRecord)` over every
 * venue and court. The banner, the idle-court runway and the mid-match edge all
 * need the same list, and `checkBlockInterruption` builds its own on every drop
 * — doing it per strip cell as well would multiply a per-tournament cost by the
 * court count on every 30-second tick.
 *
 * SCHEDULED blocks are excluded here rather than at each call site: they are
 * matchUps, already drawn as cells, and no consumer of this wants them.
 */
function loadDayBlocks(date: string): any[] {
  const { tournamentRecord } = tournamentEngine.getTournament() || {};
  if (!tournamentRecord) return [];

  let engine: any;
  try {
    engine = new AvailabilityEngine();
    engine.init(tournamentRecord);
  } catch {
    return [];
  }

  try {
    return (engine.getDayBlocks(date) || []).filter((block: any) => block?.type !== 'SCHEDULED');
  } catch {
    return [];
  }
}

/**
 * Build a courtId → ActiveStripCourtBlock map describing which availability
 * blocks are active on each court right now. Used by the live strip to
 * surface PRACTICE / MAINTENANCE / RESERVED time windows that aren't
 * matchUps. Excludes SCHEDULED blocks since those are already shown as
 * cells in the grid.
 */
function buildCurrentCourtBlocks(date: string, dayBlocks: any[]): Record<string, ActiveStripCourtBlock> {
  const { tournamentRecord } = tournamentEngine.getTournament() || {};
  if (!tournamentRecord) return {};

  const blocks = dayBlocks;
  if (!blocks.length) return {};

  // Use the strip's date as the time anchor so painted blocks on a non-today
  // date (e.g. tournament startDate) still surface as active when the
  // operator is working at the matching time-of-day.
  const now = venueNowOnDate(date);
  // A date the venue has not reached has no "now" on it, so nothing painted on
  // it is in effect. Without this the evening before an event marks every block
  // earlier than the current time-of-day as active on tomorrow's strip.
  if (!now) return {};
  const courtBlocks: Record<string, ActiveStripCourtBlock> = {};
  const activeRegsByCourtId = getActiveRegistrationNamesByCourtId({
    tournamentRecord,
    date,
    currentHM: formatHM(now),
  });

  for (const block of blocks) {
    if (!block.start || !block.end || !block.court?.courtId) continue;

    const start = new Date(block.start);
    const end = new Date(block.end);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) continue;
    if (now < start || now >= end) continue;

    const courtId = block.court.courtId;
    if (courtBlocks[courtId]) continue;

    const registrantNames = block.type === 'PRACTICE' ? activeRegsByCourtId[courtId] : undefined;
    const detail = registrantNames?.length ? registrantNames.join(', ') : block.reason || undefined;

    courtBlocks[courtId] = {
      type: block.type,
      label: `${block.type} ${formatHM(start)}–${formatHM(end)}`,
      detail,
    };
  }

  return courtBlocks;
}

/**
 * `HH:MM` from a **naive** Date — one built from a zone-less
 * `YYYY-MM-DDTHH:MM:SS` string (court block bounds, `venueNowOnDate`).
 *
 * Raw accessors are correct here and a venue-zone conversion would be the bug:
 * these values were never instants, so their digits are already venue wall
 * clock, and parsing-then-reading in the same browser zone hands them back
 * unchanged. See the "What is NOT an instant" note in `venueTimeFrame.ts`.
 */
function formatHM(d: Date): string {
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

/** Translate the factory schedule snapshot into the active-strip pure-logic shape. */
function buildActiveStripData(date: string): ActiveStripPanelData {
  const extensionMinRows = readScheduleDisplayConfig().minCourtGridRows;
  const result = getCachedScheduleMatchUps(date, {
    minCourtGridRows: extensionMinRows ?? DEFAULT_MIN_COURT_GRID_ROWS,
  });

  const rows: any[] = result.rows ?? [];
  const allCourtsData: any[] = result.courtsData ?? [];
  const courtPrefix: string = result.courtPrefix ?? 'C|';

  // Cache the full snapshot so the strip's delegated click handler can resolve
  // cellData via courtId + rowIndex without re-querying the engine.
  latestStripSnapshot = { rows, courtPrefix, courtsData: allCourtsData };

  // Mirror gridView's visible-court filter so the strip and grid agree
  const visibleCourts: { court: any; originalIndex: number }[] = [];
  for (let i = 0; i < allCourtsData.length; i++) {
    if (!hiddenCourtIds.has(allCourtsData[i].courtId)) {
      visibleCourts.push({ court: allCourtsData[i], originalIndex: i });
    }
  }

  const columns = visibleCourts.map(({ court, originalIndex }) => ({
    courtId: court.courtId,
    cells: rows.map((row) => {
      const cell = row?.[`${courtPrefix}${originalIndex}`];
      if (!cell?.matchUpId) return null;
      return {
        matchUpId: cell.matchUpId,
        drawId: cell.drawId,
        roundNumber: cell.roundNumber,
        matchUpStatus: cell.matchUpStatus,
        winningSide: cell.winningSide,
        // A pending matchUp only surfaces on the strip once it's been called to
        // court; the strip's computeActiveStripCell keys off calledAt.
        calledAt: cell.schedule?.calledAt,
        hasScore: !!(cell.score?.scoreStringSide1 || cell.score?.scoreStringSide2),
        participantIds: extractParticipantIds(cell),
        // Stash the raw factory cell so the panel's renderCell can build the
        // same grid-cell DOM (eventName, sides, score, etc.) as the grid below.
        payload: cell,
      };
    }),
  }));

  const courts = visibleCourts.map(({ court }) => ({
    courtId: court.courtId,
    label: court.courtName ?? court.courtId,
  }));

  // Match the grid's grid-template-columns (sticky row-number col + visible
  // courts + placeholder columns) so the strip's leading spacer + court cells
  // line up exactly with the grid below.
  const courtCount = visibleCourts.length;
  const emptyCalc = MINIMUM_SCHEDULE_COLUMNS - courtCount;
  const emptyCount = emptyCalc <= 0 ? 1 : emptyCalc;
  const totalColumns = courtCount + emptyCount;
  const minCourtWidthPx = readUserMinCourtWidth();
  const gridTemplateColumns = `${GRID_TIME_COL_WIDTH_PX}px repeat(${totalColumns}, minmax(${minCourtWidthPx}px, 1fr))`;
  const minWidth = `${GRID_TIME_COL_WIDTH_PX + totalColumns * minCourtWidthPx}px`;

  const dayBlocks = loadDayBlocks(date);
  const courtBlocks = buildCurrentCourtBlocks(date, dayBlocks);
  const { courtUpcomingBlocks, courtBlockEdges } = buildCourtBlockSignals(date, dayBlocks, columns, courtBlocks);

  // "Should have started by now" is only a question about today, and only on the
  // venue's clock — a director west of the tournament would otherwise read the
  // day as running late from the moment they opened it. Every other date is
  // history or plan, where nothing can be overdue.
  const dueMatchUpIds = date === todayIso() ? computeDueMatchUps(columns as any, venueClock(new Date())) : [];

  return {
    grid: { columns },
    courts,
    courtBlocks,
    courtUpcomingBlocks,
    courtBlockEdges,
    dueMatchUpIds,
    gridTemplateColumns,
    minWidth,
  };
}

/** Venue-local minutes from midnight for a naive block bound. See `formatHM` on why the raw accessors are right. */
function naiveMinutes(value: string | Date): number | undefined {
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return undefined;
  return d.getHours() * 60 + d.getMinutes();
}

/** `HH:MM` to venue-local minutes from midnight. */
function clockMinutes(value?: string): number | undefined {
  if (!value) return undefined;
  const [hh, mm] = value.split(':').map(Number);
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return undefined;
  return hh * 60 + mm;
}

/**
 * When the matchUp showing on a court's strip cell is expected to finish, in
 * venue-local minutes — or undefined when the court is idle, which is what
 * selects between the runway and the edge.
 *
 * "Showing" follows `computeActiveStripCell`'s own precedence: a live or
 * suspended matchUp, else one that has been called. An un-called pending matchUp
 * is not on the court, so the court counts as idle here — the same reading the
 * strip itself takes.
 */
function occupiedUntil(column: any, averageFor: (cell: any) => number): number | undefined {
  const live = column.cells.find(
    (cell: any) => cell && (cell.matchUpStatus === IN_PROGRESS || cell.matchUpStatus === SUSPENDED_STATUS),
  );
  const showing = live ?? column.cells.find((cell: any) => cell?.calledAt && !hasFinalResult(cell));
  if (!showing) return undefined;

  const schedule = showing.payload?.schedule ?? {};
  // Strongest anchor first: when it actually started, then when it was called,
  // then when it was due. Each is a start, so the projected finish is that plus
  // the format's average — the ladder the rest analysis walks, in miniature.
  const start =
    clockMinutes(schedule.startTime) ??
    (schedule.calledAt ? naiveMinutes(new Date(schedule.calledAt)) : undefined) ??
    clockMinutes(schedule.scheduledTime);
  if (start === undefined) return undefined;
  return start + averageFor(showing);
}

/**
 * The idle-court runway and the mid-match block edge, for every court.
 *
 * Only ever about today on the venue's clock — a block on a past or future date
 * is history or plan, and counting down to it would be arithmetic against a
 * clock that does not exist on that day.
 */
function buildCourtBlockSignals(
  date: string,
  dayBlocks: any[],
  columns: any[],
  courtBlocks: Record<string, ActiveStripCourtBlock>,
): {
  courtUpcomingBlocks: Record<string, ActiveStripUpcomingBlock>;
  courtBlockEdges: Record<string, ActiveStripUpcomingBlock>;
} {
  const courtUpcomingBlocks: Record<string, ActiveStripUpcomingBlock> = {};
  const courtBlockEdges: Record<string, ActiveStripUpcomingBlock> = {};
  if (!dayBlocks.length) return { courtUpcomingBlocks, courtBlockEdges };

  const now = venueNowOnDate(date);
  if (!now) return { courtUpcomingBlocks, courtBlockEdges };
  const nowMinutes = now.getHours() * 60 + now.getMinutes();

  const windows: CourtBlockWindow[] = [];
  for (const block of dayBlocks) {
    const courtId = block?.court?.courtId;
    if (!courtId || !block.start || !block.end) continue;
    const startMinutes = naiveMinutes(block.start);
    const endMinutes = naiveMinutes(block.end);
    if (startMinutes === undefined || endMinutes === undefined) continue;
    windows.push({ courtId, type: String(block.type), startMinutes, endMinutes });
  }
  if (!windows.length) return { courtUpcomingBlocks, courtBlockEdges };

  // The tournament's own scheduling-policy average, resolved once: the threshold
  // is "a typical match no longer fits HERE", which a hardcoded figure would get
  // wrong for any event that configured its timing.
  const averageMinutes = defaultAverageMinutes();
  const averageFor = (cell: any) => matchUpAverageMinutes(cell) ?? averageMinutes;

  for (const column of columns) {
    const courtId = column.courtId;
    // A block in force already owns this cell's second row as a banner.
    if (courtBlocks[courtId]) continue;

    const signal = courtBlockSignal({
      courtId,
      nowMinutes,
      blocks: windows,
      averageMinutes,
      occupiedUntilMinutes: occupiedUntil(column, averageFor),
    });
    if (!signal) continue;

    const runway = formatRunway(signal.minutes);
    const target = signal.kind === 'runway' ? courtUpcomingBlocks : courtBlockEdges;
    const hintKey = signal.kind === 'runway' ? 'schedule.strip.runwayHint' : 'schedule.strip.blockEdgeHint';
    target[courtId] = {
      type: signal.type,
      label: `${runway} \u2192 ${signal.type}`,
      title: t(hintKey, { minutes: runway, type: signal.type }),
    };
  }

  return { courtUpcomingBlocks, courtBlockEdges };
}

/** The scheduling policy's average for a matchUp with no format of its own. */
function defaultAverageMinutes(): number {
  try {
    const timing = competitionEngine.getMatchUpFormatTiming?.({}) as any;
    const average = Number(timing?.averageMinutes);
    return Number.isFinite(average) && average > 0 ? average : FALLBACK_AVERAGE_MINUTES;
  } catch {
    return FALLBACK_AVERAGE_MINUTES;
  }
}

/** The average for one strip cell's matchUp, or undefined when its format cannot be resolved. */
function matchUpAverageMinutes(cell: any): number | undefined {
  const matchUpFormat = resolveMatchUpFormat(cell.payload);
  if (!matchUpFormat) return undefined;
  try {
    const timing = competitionEngine.getMatchUpFormatTiming?.({
      matchUpFormat,
      eventType: cell.payload?.matchUpType,
    }) as any;
    const average = Number(timing?.averageMinutes);
    return Number.isFinite(average) && average > 0 ? average : undefined;
  } catch {
    return undefined;
  }
}

/**
 * The **venue's** calendar date for "today" — the only day the Now strip is live.
 *
 * The venue's, not the operator's: a director west of the tournament would
 * otherwise see the strip go live a day late (or early, east of it), and every
 * surface that keys "today" has to give the same answer as this one.
 */
function todayIso(): string {
  return venueToday();
}

function refreshActiveStrip(date: string): void {
  const data = buildActiveStripData(date);
  latestStripData = data;
  activeStrip?.setData(data);
  // "Now" only means something today: never auto-call on another date.
  if (date === todayIso()) runAutoCallPass(data.grid.columns);
}

/**
 * When a court has no live or already-called match, auto-call its next scheduled
 * match — unless that match's scheduledTime is strictly in the future. Runs on
 * every strip refresh (mutation + the 30s ticker), so a match is called both the
 * moment its court frees up and the moment its scheduledTime arrives. The pure
 * decision lives in computeAutoCalls; here we fire the mutation.
 *
 * FUTURE: notify the called matchUp's participants (email / push) from here.
 */
function runAutoCallPass(columns: ActiveStripPanelData['grid']['columns']): void {
  if (!currentRefresh) return;
  // Auto-call is a running-desk action, not a viewer side effect: only users
  // associated with this tournament's provider trigger it. A super-admin (or any
  // cross-provider viewer) merely observing must not stamp calledAt. Deferred:
  // a per-provider on/off toggle (default ON for provider staff) + calling roles.
  const { tournamentRecord } = tournamentEngine.getTournament() || {};
  if (!isTournamentProviderMember({ loginState: getLoginState(), tournamentRecord })) return;
  const now = new Date();
  // Compared against `scheduledTime`, which is a venue wall clock — so "now"
  // has to be one too, or the desk auto-calls on the operator's clock.
  const calls = computeAutoCalls(columns as any, venueClock(now));
  if (!calls.length) return;

  const calledAt = now.toISOString();
  const methods = calls.map((call) => ({
    method: SET_MATCHUP_CALLED_AT,
    params: { matchUpId: call.matchUpId, drawId: call.drawId, calledAt },
  }));
  executeMethods(methods, currentRefresh);
}

/**
 * Build the context for the "Now" row bulk popover. Reduces the cached strip
 * data via computeActiveStrip so the popover operates on exactly the matchUps
 * the strip shows — one active cell per visible court (LIVE, SUSP, or NEXT). The grid
 * is already visible-court filtered, so no hidden-court handling is needed here.
 */
function buildNowRowContext(refresh: () => void): Schedule2NowContext {
  const grid = latestStripData?.grid ?? { columns: [] };
  const courtLabels = new Map((latestStripData?.courts ?? []).map((c) => [c.courtId, c.label]));

  const cells = computeActiveStrip(grid)
    .filter((cell: ActiveStripCell) => cell.state !== 'free' && !!cell.matchUp)
    .map((cell: ActiveStripCell) => {
      const matchUp = cell.matchUp as NonNullable<ActiveStripCell['matchUp']>;
      const payload = matchUp.payload as any;
      return {
        matchUpId: matchUp.matchUpId,
        drawId: matchUp.drawId,
        courtId: cell.courtId,
        roundNumber: matchUp.roundNumber,
        matchUpStatus: matchUp.matchUpStatus,
        winningSide: matchUp.winningSide,
        state: cell.state,
        participantIds: matchUp.participantIds ?? [],
        sides: payload?.sides,
        courtName: courtLabels.get(cell.courtId) ?? cell.courtId,
      };
    });

  return { cells, onRefresh: refresh, executeMethods, buildDateGrid, scheduledDate: currentDate };
}

/**
 * Build a bare ActiveStripGrid for an arbitrary date across ALL courts (no
 * visible-court filter — a rescheduled match may sit on a hidden court). Used by
 * the "Now" reschedule to re-seat moved matchUps against the target date's
 * existing schedule. Mirrors buildActiveStripData's column shape, minus the
 * panel/renderCell concerns.
 */
function buildDateGrid(date: string): { columns: { courtId: string; cells: any[] }[] } {
  const result = getCachedScheduleMatchUps(date, {
    minCourtGridRows: readScheduleDisplayConfig().minCourtGridRows ?? DEFAULT_MIN_COURT_GRID_ROWS,
  });
  const rows: any[] = result.rows ?? [];
  const courtsData: any[] = result.courtsData ?? [];
  const courtPrefix: string = result.courtPrefix ?? 'C|';

  const columns = courtsData.map((court: any, index: number) => ({
    courtId: court.courtId,
    cells: rows.map((row) => {
      const cell = row?.[`${courtPrefix}${index}`];
      if (!cell?.matchUpId) return null;
      return {
        matchUpId: cell.matchUpId,
        drawId: cell.drawId,
        roundNumber: cell.roundNumber,
        matchUpStatus: cell.matchUpStatus,
        winningSide: cell.winningSide,
        participantIds: extractParticipantIds(cell),
      };
    }),
  }));

  return { columns };
}

/**
 * Shift one or more courts' placed matchUps down by N grid rows on the current
 * date — freeing the top N rows so a previous day's rain-delayed matches can be
 * inserted ABOVE an already-placed day. Opens a court picker; on apply, bumps
 * courtOrder by N for every placed matchUp on the selected courts (courtId is
 * untouched, so each match keeps its court).
 */
export function shiftCourtsDown(): void {
  const snapshot = latestStripSnapshot;
  if (!snapshot) return;

  const courts = snapshot.courtsData
    .filter((c: any) => !hiddenCourtIds.has(c.courtId))
    .map((c: any) => ({ courtId: c.courtId, label: c.courtName ?? c.courtId }));
  if (!courts.length) return;

  openShiftCourtsModal(courts, (courtIds, rows) => {
    const selected = new Set(courtIds);
    const courtPrefix = snapshot.courtPrefix;
    const methods: any[] = [];
    snapshot.courtsData.forEach((court: any, index: number) => {
      if (!selected.has(court.courtId)) return;
      snapshot.rows.forEach((row: any, ri: number) => {
        const cell = row?.[`${courtPrefix}${index}`];
        if (!cell?.matchUpId) return;
        const currentOrder = cell.schedule?.courtOrder ?? ri + 1;
        methods.push({
          method: ADD_MATCHUP_SCHEDULE_ITEMS,
          params: {
            matchUpId: cell.matchUpId,
            drawId: cell.drawId,
            schedule: { courtOrder: currentOrder + rows },
            removePriorValues: true,
          },
        });
      });
    });
    if (methods.length && currentRefresh) executeMethods(methods, currentRefresh);
  });
}

/**
 * Resolve player conflicts on the selected day by invoking the factory
 * `proColumnResolve` mutation: it re-lays the grid vertically (courtOrder +
 * inserted blank rows) so conflicting matchUps land on different rows, WITHOUT
 * changing any match's court or scheduledTime. Confirm-first; whole grid.
 *
 * We count the currently-flagged participant / potential-participant conflicts
 * client-side (same `proConflicts` the header/row indicators use) to decide
 * whether there is anything to do. After the mutation, the grid refresh re-runs
 * those indicators, so any conflict the resolver could NOT fix (e.g. a feeder
 * scheduled at a later time than the match it feeds) stays visibly highlighted.
 */
export function resolveColumnConflicts(): void {
  if (!currentRefresh || !currentDate) return;

  const conflictResult = getCachedProConflicts(currentDate);
  const { scheduledMatchUps } = conflictResult;
  if (!scheduledMatchUps.length) {
    scheduleToast({ message: t('gridView.noScheduled'), intent: INTENT_WARNING });
    return;
  }

  const { CONFLICT_PARTICIPANTS, CONFLICT_POTENTIAL_PARTICIPANTS, SCHEDULE_CONFLICT } = scheduleConstants;
  const participantConflicts = Object.values(conflictResult.rowIssues || {})
    .flat()
    .filter(
      (issue: any) =>
        issue?.issue === SCHEDULE_CONFLICT &&
        (issue.issueType === CONFLICT_PARTICIPANTS || issue.issueType === CONFLICT_POTENTIAL_PARTICIPANTS),
    );
  if (!participantConflicts.length) {
    scheduleToast({ message: t('gridView.noConflicts'), intent: INTENT_SUCCESS });
    return;
  }

  confirmModal({
    title: t('gridView.resolveConflicts'),
    query:
      `Space matches down to clear player conflicts on ${currentDate}. ` +
      'Courts and start times stay the same — only the row order changes. Continue?',
    okIntent: 'is-warning',
    okAction: () => {
      const methods = [
        { method: PRO_COLUMN_RESOLVE, params: { scheduledDate: currentDate, matchUps: scheduledMatchUps } },
      ];
      if (currentRefresh) executeMethods(methods, currentRefresh);
    },
  });
}

/**
 * Give the "Now" spacer a pointer affordance. The click itself is delegated on
 * the strip root; this only styles the spacer so it reads as actionable. Runs
 * on a delegated pointer basis so it survives the strip's render() rebuilds.
 */
function makeSpacerInteractive(stripEl: HTMLElement): void {
  stripEl.addEventListener('pointerover', (e) => {
    const spacer = (e.target as HTMLElement | null)?.closest('.spl-active-strip-spacer') as HTMLElement | null;
    if (spacer) spacer.style.cursor = 'pointer';
  });
}

/**
 * Click handler for active-strip cells — opens the same popover as grid cells.
 * Resolves cellData from the cached schedule snapshot via courtId + rowIndex.
 */
function handleStripCellClick(event: MouseEvent, cellRoot: HTMLElement, refresh: () => void): void {
  if (!latestStripSnapshot) return;

  const courtId = cellRoot.dataset.courtId ?? '';
  if (!courtId) return;

  // `dataset` yields undefined where getAttribute yielded null — the absent case
  // still means row 0, and an empty string still coerces to 0 as before.
  const rowAttr = cellRoot.dataset.rowIndex;
  const rowIndex = rowAttr === undefined ? 0 : Number(rowAttr);

  const courtIndex = latestStripSnapshot.courtsData.findIndex((c) => c.courtId === courtId);
  if (courtIndex < 0) return;

  const court = latestStripSnapshot.courtsData[courtIndex];
  const cellKey = `${latestStripSnapshot.courtPrefix}${courtIndex}`;
  const cellData = latestStripSnapshot.rows[rowIndex]?.[cellKey];
  const courtOrder = cellData?.schedule?.courtOrder ?? rowIndex + 1;

  handleSchedule2CellClick(event, {
    cellData,
    courtId,
    venueId: court?.venueId ?? '',
    courtOrder,
    scheduledDate: currentDate,
    allRows: latestStripSnapshot.rows,
    courtPrefix: latestStripSnapshot.courtPrefix,
    rowIndex,
    onRefresh: refresh,
    executeMethods,
    matchUpListProvider: () => getFilteredMatchUpList(currentDate, activeControl),
    findCatalogItem: (mid: string) => buildCatalog(currentDate).find((m) => m.matchUpId === mid),
    // The strip books by clock, not by grid row — see `Schedule2CellContext.surface`.
    surface: 'strip',
    blockCourtsProvider: () => blockableCourts(),
  });
}

/**
 * Every court the time-block modal can write to, with the `dateAvailability` it
 * has to read-modify-write.
 *
 * Read fresh on open rather than captured with the strip's snapshot: the modal
 * is a separate interaction, and writing back an array that was read minutes ago
 * would silently drop whatever another client did in between.
 */
function blockableCourts(): TimeBlockCourt[] {
  const { tournamentRecord }: any = tournamentEngine.getTournament() ?? {};
  return ((tournamentRecord?.venues ?? []) as any[])
    .flatMap((venue: any) => venue.courts ?? [])
    .map((court: any) => ({
      courtId: court.courtId,
      courtName: court.courtName ?? court.courtId,
      dateAvailability: court.dateAvailability ?? [],
    }));
}

/** Drop handler for the active strip — uses the resolved (courtId, rowIndex). */
/**
 * Pre-drop affordance for the Now strip. While a GRID matchUp is dragged over a
 * court whose Now slot is already occupied, show the OS "not-allowed" cursor
 * (dropEffect = 'none') and a danger outline, and suppress the component's
 * valid-target highlight — so the rejection enforced by handleActiveStripDrop
 * is visible before the drop. Catalog drags and free cells are unaffected.
 *
 * Delegated on the strip root (not per-cell) so it survives the strip's
 * re-renders, which rebuild the cell DOM on every setData.
 */
function attachStripDropAffordance(stripEl: HTMLElement): void {
  const findCell = (node: EventTarget | null): HTMLElement | null => {
    let el = node as HTMLElement | null;
    while (el && el !== stripEl && !el.classList?.contains(STRIP_CELL_CLASS)) {
      el = el.parentElement;
    }
    return el?.classList?.contains(STRIP_CELL_CLASS) ? el : null;
  };
  const clearBlocked = (cell: HTMLElement): void => {
    cell.classList.remove(STRIP_DROP_BLOCKED_CLASS);
    cell.style.outline = '';
    cell.style.outlineOffset = '';
  };

  stripEl.addEventListener('dragover', (e) => {
    const cell = findCell(e.target);
    if (!cell) return;
    const isGridDrag = !!e.dataTransfer?.types?.includes(GRID_DRAG_MARKER);
    const occupied = !cell.classList.contains(STRIP_FREE_CLASS);
    if (isGridDrag && occupied) {
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'none';
      cell.classList.remove(DROP_OVER_CLASS); // kill the component's valid-target highlight
      cell.classList.add(STRIP_DROP_BLOCKED_CLASS);
      cell.style.outline = '2px solid var(--sp-danger, #ef4444)';
      cell.style.outlineOffset = '-2px';
    } else {
      clearBlocked(cell);
    }
  });
  stripEl.addEventListener('dragleave', (e) => {
    const cell = findCell(e.target);
    if (cell) clearBlocked(cell);
  });
  stripEl.addEventListener('drop', (e) => {
    const cell = findCell(e.target);
    if (cell) clearBlocked(cell);
  });
}

function handleActiveStripDrop(
  payload: { type: 'CATALOG_MATCHUP' | 'GRID_MATCHUP'; matchUp: any },
  target: { courtId: string; rowIndex: number },
  refresh: () => void,
  event?: DragEvent,
): void {
  // A matchUp dragged FROM the grid may only land on an EMPTY Now-strip cell.
  // If the court's Now slot already shows a live/next matchUp, reject the drop —
  // the strip is what's imminent and shouldn't be displaced by a grid drag.
  // Catalog drags are unaffected; re-dropping the same matchUp is a no-op.
  if (payload.type === 'GRID_MATCHUP' && event) {
    let cellEl = event.target as HTMLElement | null;
    while (cellEl && !cellEl.classList?.contains(STRIP_CELL_CLASS)) {
      cellEl = cellEl.parentElement;
    }
    if (cellEl) {
      const reject = shouldRejectStripDrop({
        payloadType: payload.type,
        draggedMatchUpId: payload.matchUp.matchUpId,
        cellOccupied: !cellEl.classList.contains(STRIP_FREE_CLASS),
        occupantMatchUpId: cellEl.querySelector(`[${DATA_MATCHUP_ID}]`)?.getAttribute(DATA_MATCHUP_ID),
      });
      if (reject) {
        scheduleToast({ message: t('gridView.nowOccupied'), intent: INTENT_WARNING });
        return;
      }
    }
  }

  const extensionMinRows = readScheduleDisplayConfig().minCourtGridRows;
  const result = getCachedScheduleMatchUps(currentDate, {
    minCourtGridRows: extensionMinRows ?? DEFAULT_MIN_COURT_GRID_ROWS,
  });
  const courtsData: any[] = result.courtsData ?? [];
  const court = courtsData.find((c) => c.courtId === target.courtId);
  if (!court) return;

  // Row #2.7 — when an availability block on this court would either be
  // active right now OR start before the matchUp's average duration
  // completes, surface a confirm modal so the TD makes the call
  // deliberately. Skip when no block info or no format timing is
  // available; the original drop behavior stands in those cases.
  const blockCheck = checkBlockInterruption(payload.matchUp, target.courtId);
  if (blockCheck) {
    const title =
      blockCheck.kind === 'active'
        ? `Court currently has ${blockCheck.blockType}`
        : 'Court will be unavailable before this matchUp completes';
    const query =
      blockCheck.kind === 'active'
        ? `${blockCheck.blockType} runs until ${blockCheck.edgeLabel} on this court — only ${blockCheck.availableMinutes} min until the court is free. Expected play time is ~${blockCheck.averageMinutes} min. Schedule anyway?`
        : `${blockCheck.blockType} starts at ${blockCheck.edgeLabel} on this court. Expected play time is ~${blockCheck.averageMinutes} min, leaving only ${blockCheck.availableMinutes} min before the block. Schedule anyway?`;
    confirmModal({
      title,
      query,
      okIntent: INTENT_WARNING,
      okAction: () => commitActiveStripDrop(payload, target, court, refresh),
    });
    return;
  }

  commitActiveStripDrop(payload, target, court, refresh);
}

function commitActiveStripDrop(
  payload: { type: 'CATALOG_MATCHUP' | 'GRID_MATCHUP'; matchUp: any },
  target: { courtId: string; rowIndex: number },
  court: any,
  refresh: () => void,
): void {
  const courtOrder = target.rowIndex + 1;

  // WARN and proceed, never block (D4d). The active-strip drop IS the call to court, so declining
  // cancels the whole drop rather than landing the match uncalled — a half-applied drop would leave
  // the grid asserting a placement the operator did not choose.
  //
  // The catalog payload cannot answer this: `CatalogMatchUpItem` carries no `checkedInParticipantIds`,
  // so the hydrated matchUp has to be resolved. Autocall deliberately skips this prompt (D4f).
  const dropped = getCachedAllMatchUps()?.matchUps?.find(
    (matchUp: any) => matchUp?.matchUpId === payload.matchUp.matchUpId,
  );
  const prompt = callToCourtPrompt(dropped);
  const gated =
    prompt &&
    shouldPromptOnCall({
      mode: readCheckInPromptMode(),
      inUse: checkInInUse(getCachedAllMatchUps()?.matchUps, currentDate),
      awaitingCount: prompt.awaitingCount,
    });
  if (
    gated &&
    !globalThis.confirm(`${t('checkIn.callOnDropBeforeCheckIn', { count: prompt.awaitingCount })}\n\n${prompt.names}`)
  )
    return;

  const methods: any[] = [];

  if (payload.type === 'GRID_MATCHUP') {
    // Clear the matchUp's prior grid placement (court/order/venue) before it
    // lands on the strip — but intentionally PRESERVE scheduledTime. Calling a
    // match to court doesn't erase its planned time; omitting scheduledTime here
    // leaves the existing value untouched (removePriorValues acts per-attribute).
    methods.push({
      method: ADD_MATCHUP_SCHEDULE_ITEMS,
      params: {
        matchUpId: payload.matchUp.matchUpId,
        drawId: payload.matchUp.drawId ?? '',
        schedule: { scheduledDate: '', courtOrder: '', venueId: '', courtId: '' },
        removePriorValues: true,
      },
    });
  }

  methods.push({
    method: ADD_MATCHUP_SCHEDULE_ITEMS,
    params: {
      matchUpId: payload.matchUp.matchUpId,
      drawId: payload.matchUp.drawId ?? '',
      schedule: {
        courtOrder,
        scheduledDate: currentDate,
        courtId: target.courtId,
        venueId: court.venueId,
      },
      removePriorValues: true,
    },
  });

  // Stamp the "called to court" timestamp — the active-strip drop is the
  // deliberate signal that this matchUp is imminent. Distinct from regular
  // grid drops (which leave calledAt untouched as historical record).
  methods.push({
    method: SET_MATCHUP_CALLED_AT,
    params: {
      matchUpId: payload.matchUp.matchUpId,
      drawId: payload.matchUp.drawId ?? '',
      calledAt: new Date().toISOString(),
    },
  });

  // Start-on-drop: a TD dragging to Now often intends to START the match, not
  // just call it. The start methods (startTime + IN_PROGRESS) are only produced
  // when the match is actually startable — otherwise the drop is a pure call.
  // Start-on-drop is only meaningful today — a drop on a past/future strip calls
  // the match to court but never starts it.
  const startMethods =
    currentDate === todayIso() ? buildStartOnDropMethods(payload.matchUp.matchUpId, payload.matchUp.drawId ?? '') : [];
  const cfg = readScheduleDisplayConfig();
  const prompted = cfg.startOnDropPrompted;

  if (startMethods.length && prompted && cfg.startOnDrop) {
    // Preference already opted-in — start atomically with the call to court.
    methods.push(...startMethods);
  }

  executeMethods(methods, refresh);

  // First time a startable match lands on Now, ask once and remember the choice.
  // The call to court has already committed above; only the start is deferred.
  if (startMethods.length && !prompted) {
    confirmModal({
      title: t('schedule.startOnDropTitle'),
      query: t('schedule.startOnDropPrompt'),
      okIntent: 'is-info',
      okAction: () => {
        writeScheduleDisplayConfig({ startOnDrop: true, startOnDropPrompted: true });
        executeMethods(startMethods, refresh);
      },
      cancelAction: () => writeScheduleDisplayConfig({ startOnDrop: false, startOnDropPrompted: true }),
    });
  }
}

/**
 * Build the [startTime, IN_PROGRESS] mutation pair for a start-on-drop, or an
 * empty array when the matchUp can't be started (already in progress, decided,
 * or missing a second participant). Reads authoritative status/sides from the
 * cached matchUps rather than the drag payload, which may be stale.
 */
function buildStartOnDropMethods(matchUpId: string, drawId: string): any[] {
  const { matchUps } = getCachedAllMatchUps() || {};
  const matchUp = (matchUps || []).find((m: any) => m.matchUpId === matchUpId);
  if (!matchUp || matchUp.matchUpStatus === IN_PROGRESS || matchUp.winningSide) return [];

  const assigned = (matchUp.sides || []).filter((s: any) => s?.participantId || s?.participant?.participantId).length;
  if (assigned < 2) return [];

  // `startTime` is stored as a bare venue wall clock, so it must be read off the
  // venue's clock rather than the operator's.
  const startTime = venueNowClock();
  return [
    {
      method: BULK_SCHEDULE_MATCHUPS,
      params: { matchUpIds: [matchUpId], schedule: { startTime }, removePriorValues: true },
    },
    {
      method: SET_MATCHUP_STATUS,
      params: { matchUpId, drawId, outcome: { matchUpStatus: IN_PROGRESS } },
    },
  ];
}

/**
 * Inverse of buildStartOnDropMethods: when a matchUp is removed from the grid
 * back to the catalog (unscheduled), a match that was called/started-on-drop
 * but never actually scored must not stay IN_PROGRESS — an IN_PROGRESS matchUp
 * off-court is a phantom that lets two matches in the same column both read as
 * live, which is impossible on one court. Revert it to TO_BE_PLAYED and clear
 * the start time. A match with any score entered keeps its status (it genuinely
 * started); only the empty-score case is un-started. Reads authoritative
 * status/score from the cache rather than the drag payload, which may be stale.
 */
function buildUnstartOnRemoveMethods(matchUpId: string, drawId: string): any[] {
  const { matchUps } = getCachedAllMatchUps() || {};
  const matchUp = (matchUps || []).find((m: any) => m.matchUpId === matchUpId);
  if (!matchUp || matchUp.matchUpStatus !== IN_PROGRESS) return [];
  if (matchUp.winningSide || scoreGovernor.checkScoreHasValue(matchUp)) return [];

  return [
    {
      method: BULK_SCHEDULE_MATCHUPS,
      params: { matchUpIds: [matchUpId], schedule: { startTime: '' }, removePriorValues: true },
    },
    {
      method: SET_MATCHUP_STATUS,
      params: { matchUpId, drawId, outcome: { matchUpStatus: TO_BE_PLAYED } },
    },
  ];
}

/**
 * Resolve the effective matchUpFormat for a matchUp. The catalog payload
 * often lacks a matchUpFormat (inherited from the drawDefinition); fall back
 * to that draw's format so downstream timing lookups work.
 */
function resolveMatchUpFormat(matchUp: any): string | undefined {
  if (matchUp?.matchUpFormat) return matchUp.matchUpFormat;
  const drawId = matchUp?.drawId;
  if (!drawId) return undefined;
  const { tournamentRecord } = tournamentEngine.getTournament() || {};
  if (!tournamentRecord) return undefined;
  for (const event of tournamentRecord.events || []) {
    for (const draw of event.drawDefinitions || []) {
      if (draw.drawId === drawId) return draw.matchUpFormat;
    }
  }
  return undefined;
}

interface BlockInterruptionWarning {
  /** 'active' when the block is in effect right now; 'upcoming' when it starts later. */
  kind: 'active' | 'upcoming';
  blockType: string;
  /** For 'upcoming': start time. For 'active': end time. */
  edgeLabel: string;
  averageMinutes: number;
  /** Minutes between "now" and the block edge that matters (start for upcoming, end for active). */
  availableMinutes: number;
}

/**
 * Returns warning details when scheduling the given matchUp on a court at
 * "now" would conflict with an availability block — either an active block
 * the matchUp would overlap, or an upcoming block that would interrupt the
 * matchUp before its average duration completes. Returns undefined when no
 * conflict — caller proceeds directly to the drop commit.
 */
function checkBlockInterruption(matchUp: any, courtId: string): BlockInterruptionWarning | undefined {
  const { tournamentRecord } = tournamentEngine.getTournament() || {};
  if (!tournamentRecord) return undefined;

  const matchUpFormat = resolveMatchUpFormat(matchUp);
  if (!matchUpFormat) return undefined;

  // Average minutes for this matchUp format under the active scheduling timing.
  let timing: any;
  try {
    timing = competitionEngine.getMatchUpFormatTiming?.({
      matchUpFormat,
      eventType: matchUp.matchUpType,
    });
  } catch {
    return undefined;
  }
  const averageMinutes = Number(timing?.averageMinutes);
  if (!averageMinutes || !Number.isFinite(averageMinutes) || averageMinutes <= 0) return undefined;

  let engine: any;
  try {
    engine = new AvailabilityEngine();
    engine.init(tournamentRecord);
  } catch {
    return undefined;
  }

  let blocks: any[];
  try {
    blocks = engine.getDayBlocks(currentDate) || [];
  } catch {
    return undefined;
  }
  if (!blocks.length) return undefined;

  const now = venueNowOnDate(currentDate);
  // The whole check is anchored on "now" — an active block overlapping it, or
  // the next one arriving before the matchUp could finish. A future date has no
  // now to anchor on, so there is no conflict to report: take the same exit as
  // missing block data, where the caller's documented behaviour is that the
  // original drop stands.
  if (!now) return undefined;

  // First: is a non-SCHEDULED block currently active on this court?
  for (const block of blocks) {
    if (block?.type === 'SCHEDULED') continue;
    if (!block.start || !block.end || block.court?.courtId !== courtId) continue;
    const start = new Date(block.start);
    const end = new Date(block.end);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) continue;
    if (now >= start && now < end) {
      const minutesUntilEnd = Math.max(0, Math.floor((end.getTime() - now.getTime()) / 60000));
      return {
        kind: 'active',
        blockType: String(block.type),
        edgeLabel: formatHM(end),
        averageMinutes,
        availableMinutes: minutesUntilEnd,
      };
    }
  }

  // Otherwise: does an upcoming block start before this matchUp could complete?
  // `any` already admits undefined; `any | undefined` collapses to `any` and
  // SonarJS flags the redundant member.
  let nextBlock: any;
  for (const block of blocks) {
    if (block?.type === 'SCHEDULED') continue;
    if (!block.start || block.court?.courtId !== courtId) continue;
    const start = new Date(block.start);
    if (Number.isNaN(start.getTime()) || start <= now) continue;
    if (!nextBlock || start < new Date(nextBlock.start)) nextBlock = block;
  }
  if (!nextBlock) return undefined;

  const availableMinutes = Math.floor((new Date(nextBlock.start).getTime() - now.getTime()) / 60000);
  if (availableMinutes >= averageMinutes) return undefined;

  return {
    kind: 'upcoming',
    blockType: String(nextBlock.type),
    edgeLabel: formatHM(new Date(nextBlock.start)),
    averageMinutes,
    availableMinutes: Math.max(availableMinutes, 0),
  };
}

/**
 * Single source of truth for "scheduled but not placed" — used by both the
 * Scheduled-panel renderer and the tab badge so they cannot drift. Sorted by
 * scheduledTime ascending (no-time entries fall to the bottom) so that the list
 * reflects the play order produced by the scheduler, with a stable tie-break on
 * matchUpId.
 *
 * Orphans = scheduled-for-this-date, no court assigned, not BYE. Completion
 * status is NOT filtered here — callers decide based on the operator's
 * "Show completed" toggle. Splitting the call this way lets `updateBadge`
 * compute both the visible count (respects the toggle) and the absolute count
 * (drives funnel visibility) from one factory call.
 *
 * Takes `scheduledDate` explicitly rather than reading the module-level
 * `currentDate` it used to close over: pure given its input, so it is
 * independently testable and is not re-created on every render pass.
 */
function listScheduledOrphans(scheduledDate: string): any[] {
  const { matchUps } = getCachedAllMatchUps();
  const filtered = (matchUps || []).filter((m: any) => {
    if (m.matchUpStatus === BYE) return false;
    if (m.schedule?.scheduledDate !== scheduledDate) return false;
    if (m.schedule?.courtId) return false; // already on a court — don't show
    return true; // date match is sufficient — time is optional
  });
  filtered.sort((a: any, b: any) => {
    const am = scheduledTimeToMinutes(a.schedule?.scheduledTime);
    const bm = scheduledTimeToMinutes(b.schedule?.scheduledTime);
    if (am !== bm) return am - bm;
    return String(a.matchUpId).localeCompare(String(b.matchUpId));
  });
  return filtered;
}

/**
 * Map a raw matchUp (from competitionEngine.allTournamentMatchUps) into the
 * CatalogMatchUpItem shape expected by buildMatchUpCard. Used by the Scheduled
 * sidebar panel so it can render the same card component as the Unscheduled
 * catalog. `isScheduled` is forced to false so dragstart wires up — the
 * prominent-time option on buildMatchUpCard handles the visual differentiation.
 */
function scheduledMatchUpToCatalogItem(m: any): CatalogMatchUpItem {
  return {
    matchUpId: m.matchUpId,
    eventId: m.eventId ?? '',
    eventName: m.eventName ?? '',
    drawId: m.drawId ?? '',
    drawName: m.drawName,
    structureId: m.structureId ?? '',
    structureName: m.structureName,
    stage: m.stage,
    roundNumber: m.roundNumber ?? 0,
    roundName: m.roundName,
    matchUpFormat: m.matchUpFormat,
    matchUpType: m.matchUpType,
    matchUpStatus: m.matchUpStatus,
    gender: m.gender,
    sides: (m.sides || []).map((s: any) => ({
      participantName: s.participant?.participantName ?? s.participantName,
      participantId: s.participantId ?? s.participant?.participantId,
      seedNumber: s.seedValue ?? s.seedNumber,
      individualParticipants: s.participant?.individualParticipants,
    })),
    isScheduled: false,
    scheduledTime: m.schedule?.scheduledTime,
    scheduledCourtName: m.schedule?.courtName,
  };
}

// Active plan's placements keyed by matchUpId (empty outside Plan mode).
function planPlacementMap(): { [matchUpId: string]: any } {
  if (!planContext) return {};
  const scenario = listScheduleScenarios(planContext.tournamentId).find(
    (s: any) => s.scenarioId === planContext?.scenarioId,
  );
  const map: { [matchUpId: string]: any } = {};
  for (const p of scenario?.placements ?? []) map[p.matchUpId] = p.schedule ?? {};
  return map;
}

// A matchUp's schedule as the plan sees it: the scenario placement when present
// (and the matchUp is uncompleted — the plan skips completed matchUps), else the
// official schedule.
function effectiveMatchUpSchedule(m: any, placements: { [matchUpId: string]: any }): any {
  const override = placements[m.matchUpId];
  if (!override) return m.schedule;
  const completed = m.winningSide || isCompletedStatus(m.matchUpStatus);
  return completed ? m.schedule : override;
}

function buildCatalog(selectedDate: string): CatalogMatchUpItem[] {
  const { matchUps } = getCachedAllMatchUps();
  // In Plan mode the catalog reflects the PROJECTED plan, not the official
  // schedule: a match the plan schedules leaves the catalog; a match the plan
  // unschedules returns to it. Overlay the active scenario's placements onto
  // each matchUp's schedule. An empty map (grid mode) ⇒ official schedule.
  const placements = planPlacementMap();

  return (matchUps || [])
    .filter((m: any) => {
      if (m.matchUpStatus === BYE) return false;
      // A matchUp scheduled on a DIFFERENT date does not belong in this date's
      // catalog — its chips reference that other day. (Projected schedule in
      // Plan mode.)
      const scheduledDate = effectiveMatchUpSchedule(m, placements)?.scheduledDate;
      if (scheduledDate && scheduledDate !== selectedDate) return false;
      return true;
    })
    .map((m: any) => {
      // After the filter above, any `scheduledDate` we see is the selected
      // date, so onSelectedDate is implicit — collapse to a single isScheduled
      // check. Uses the projected (plan-overlaid) schedule in Plan mode.
      const schedule = effectiveMatchUpSchedule(m, placements);
      const hasDate = !!schedule?.scheduledDate;
      const hasCourtAssignment = !!(schedule?.courtId && hasDate);
      const hasTimeAssignment = !!(schedule?.scheduledTime && hasDate);
      const isScheduled = hasCourtAssignment || hasTimeAssignment || hasDate;

      return {
        matchUpId: m.matchUpId,
        eventId: m.eventId ?? '',
        eventName: m.eventName ?? '',
        drawId: m.drawId ?? '',
        drawName: m.drawName,
        structureId: m.structureId ?? '',
        structureName: m.structureName,
        stage: m.stage,
        roundNumber: m.roundNumber ?? 0,
        roundName: m.roundName,
        matchUpFormat: m.matchUpFormat,
        matchUpType: m.matchUpType,
        matchUpStatus: m.matchUpStatus,
        gender: m.gender,
        sides: (m.sides || []).map((s: any) => ({
          participantName: s.participant?.participantName ?? s.participantName,
          participantId: s.participantId ?? s.participant?.participantId,
          seedNumber: s.seedValue ?? s.seedNumber,
          individualParticipants: s.participant?.individualParticipants,
        })),
        isScheduled,
        scheduledTime: isScheduled ? schedule?.scheduledTime : undefined,
        scheduledCourtName: isScheduled ? schedule?.courtName : undefined,
      } satisfies CatalogMatchUpItem;
    });
}

export function buildScheduleDates(selectedDate: string): ScheduleDate[] {
  const { startDate, endDate } = getCachedCompetitionDateRange();
  const { tournamentInfo } = getCachedTournamentInfo();
  const activeDates = tournamentInfo?.activeDates;
  const dates = activeDates?.length ? [...activeDates].sort() : plainDateRange(startDate ?? '', endDate ?? '');

  const { matchUps } = getCachedAllMatchUps();
  const dateCounts = new Map<string, number>();
  for (const m of matchUps || []) {
    if (m.matchUpStatus === BYE) continue;
    const d = m.schedule?.scheduledDate;
    if (d) dateCounts.set(d, (dateCounts.get(d) || 0) + 1);
  }

  const publishState = getOrderOfPlayPublishState();

  return dates.map((date: string) => ({
    date,
    isActive: date === selectedDate,
    isPublished: isOrderOfPlayDatePublished(date, publishState),
    matchUpCount: dateCounts.get(date) ?? 0,
  }));
}

/**
 * Apply issue severity indicators to court column headers and row number labels.
 * Uses a left border accent matching the cell issue colors.
 *
 * Gated on the same warning-bars preference as the cells. Leaving the headers out of it
 * would be half a feature: the cells would go quiet while every court column kept a
 * yellow underline, which is the same noise the operator turned off, drawn one row
 * higher. Errors are never filtered, so a red header survives regardless.
 */
function applyHeaderRowIssueIndicators(
  courtHeaders: HTMLElement[],
  rowLabels: HTMLElement[],
  courtsData: any[],
  selectedDate: string,
): void {
  // Use allTournamentMatchUps for conflict detection (grid cell data lacks fields proConflicts needs).
  // Shared with `buildIssues` through the cache: same question, same input.
  const result = getCachedProConflicts(selectedDate);
  if (!result.evaluated) return;

  const warningBarsVisible = readGridWarningBars();
  /** Drops the issues whose decoration the operator has turned off. Errors always survive. */
  const decorated = (issues: any[] | undefined): any[] =>
    (issues ?? []).filter((issue) => decoratesCell(issue?.issue, warningBarsVisible));
  const conflicts = { courtIssues: result.courtIssues || {}, rowIssues: result.rowIssues || {} };

  const { SCHEDULE_ERROR, SCHEDULE_CONFLICT, SCHEDULE_WARNING } = scheduleConstants;

  // Issues from proConflicts are pushed in event-iteration order, not severity order.
  // Pick the highest severity so a red error always wins over a yellow warning.
  const severityRank = (issue: string): number => {
    if (issue === SCHEDULE_ERROR || issue === SCHEDULE_CONFLICT) return 2;
    if (issue === SCHEDULE_WARNING) return 1;
    return 0;
  };
  // Seeded with the first issue so the accumulator is a plain severity string.
  // Both callers already guard `!issues?.length`, but a seedless reduce THROWS on
  // an empty array — the seed makes this correct on its own terms rather than
  // dependent on those guards staying in place. Equivalent for non-empty input.
  const topSeverity = (issues: any[]): string =>
    issues.reduce(
      (top, cur) => (severityRank(cur.issue) > severityRank(top) ? cur.issue : top),
      issues[0]?.issue ?? '',
    );

  const severityColor = (issue: string): string => {
    if (issue === SCHEDULE_ERROR || issue === SCHEDULE_CONFLICT) return 'var(--sp-err, #f43f5e)';
    if (issue === SCHEDULE_WARNING) return 'var(--sp-warn, #f59e0b)';
    return 'var(--sp-accent, #3b82f6)';
  };

  // Semi-transparent tint for headers (they don't overlap scrolling content)
  const severityBg = (issue: string): string => {
    if (issue === SCHEDULE_ERROR || issue === SCHEDULE_CONFLICT) return 'rgba(244, 63, 94, 0.08)';
    if (issue === SCHEDULE_WARNING) return 'rgba(245, 158, 11, 0.06)';
    return 'rgba(59, 130, 246, 0.06)';
  };

  // Opaque tint for sticky row labels — layers a semi-transparent tint over the panel bg
  // so it works in both light and dark mode while hiding scrolling content behind it
  const severityBgOpaque = (issue: string): string => {
    const tint = severityBg(issue);
    return `linear-gradient(${tint}, ${tint}), var(--sp-panel-bg, #fff)`;
  };

  // Court headers: match courtId from courtsData to courtIssues keys
  for (let ci = 0; ci < courtHeaders.length; ci++) {
    const courtId = courtsData[ci]?.courtId;
    if (!courtId) continue;
    const issues = decorated(conflicts.courtIssues[courtId]);
    if (!issues.length) continue;
    const topIssue = topSeverity(issues);
    courtHeaders[ci].style.borderBottom = `3px solid ${severityColor(topIssue)}`;
    courtHeaders[ci].style.background = severityBgOpaque(topIssue);
  }

  // Row labels: rowIssues keyed by row index
  const rowIssueEntries = conflicts.rowIssues || {};
  for (const [rowIdx, rawIssues] of Object.entries(rowIssueEntries)) {
    const ri = Number.parseInt(rowIdx);
    const issues = decorated(rawIssues as any[]);
    if (Number.isNaN(ri) || ri >= rowLabels.length || !issues.length) continue;
    const topIssue = topSeverity(issues);
    rowLabels[ri].style.borderRight = `3px solid ${severityColor(topIssue)}`;
    rowLabels[ri].style.background = severityBgOpaque(topIssue);
  }
}

/**
 * `matchUpId` -> the one issue that decides its cell, from a `proConflicts` result.
 *
 * Row issues win over court issues on a tie: a row issue is about the matchUp's place in
 * the order of play, which is what the cell's own decoration is saying. Extracted to
 * module level rather than inlined — `annotateConflicts` sits right against the
 * cognitive-complexity ceiling, and a nested builder is what pushes it over.
 */
function buildMatchUpIssueMap(courtIssues: any, rowIssues: any): Map<string, any> {
  const matchUpIssueMap = new Map<string, any>();

  if (rowIssues) {
    const flatIssues = Array.isArray(rowIssues) ? rowIssues.flat() : Object.values(rowIssues).flat();
    for (const issue of flatIssues as any[]) {
      if (issue.matchUpId) matchUpIssueMap.set(issue.matchUpId, issue);
    }
  }

  if (courtIssues) {
    for (const issues of Object.values(courtIssues)) {
      for (const issue of issues as any[]) {
        if (issue.matchUpId && !matchUpIssueMap.has(issue.matchUpId)) matchUpIssueMap.set(issue.matchUpId, issue);
      }
    }
  }

  return matchUpIssueMap;
}

/**
 * Run proConflicts and annotate cellData objects with scheduleState, issueType,
 * and issueIds so that buildScheduleGridCell applies the correct CSS classes.
 *
 * **Warning-severity decoration is suppressible, and this is the only place it can be
 * done from.** `courthive-components` derives `.spl-cell--warning` from `scheduleState`
 * alone (`scheduleGridCell.ts` -> `applyStatusClasses`), so withholding the annotation
 * here removes the bar with no change to that library and no publish cascade. Filtering
 * downstream of the annotation would mean teaching the component a preference it has no
 * business knowing about.
 *
 * `delete` rather than "annotate nothing": these cellData objects are shallow clones of
 * a CACHED row, so a stale annotation from a previous render survives into this one
 * unless it is removed. That is why the else-branch already existed, and it is why a
 * suppressed warning must take the same branch rather than simply being skipped.
 */
function annotateConflicts(rows: any[], courtsData: any[], courtPrefix: string): void {
  // Collect all matchUp cellData objects from the grid
  const allCellData: any[] = [];
  for (const row of rows) {
    for (let ci = 0; ci < courtsData.length; ci++) {
      const cellData = row[`${courtPrefix}${ci}`];
      if (cellData?.matchUpId) allCellData.push(cellData);
    }
  }

  if (!allCellData.length) return;

  const { courtIssues, rowIssues } = unwrapOr(competitionEngine.proConflicts({ matchUps: allCellData }), {
    courtIssues: {},
    rowIssues: {},
  });

  const matchUpIssueMap = buildMatchUpIssueMap(courtIssues, rowIssues);

  // Annotate each cellData with the issue info that mapMatchUpToCellData reads
  const warningBarsVisible = readGridWarningBars();
  for (const cellData of allCellData) {
    const issue = matchUpIssueMap.get(cellData.matchUpId);
    if (issue && decoratesCell(issue.issue, warningBarsVisible)) {
      cellData.scheduleState = issue.issue;
      cellData.issueType = issue.issueType;
      cellData.issueIds = issue.issueIds;
    } else {
      delete cellData.scheduleState;
      delete cellData.issueType;
      delete cellData.issueIds;
    }
  }
}

function buildIssueEntry(
  issue: any,
  mapSeverity: (issue: string) => ScheduleIssueSeverity,
  labelFn: (id: string) => string,
  selectedDate: string,
  prefix?: string,
): ScheduleIssue {
  const participants = labelFn(issue.matchUpId);
  const conflictLabels = (issue.issueIds || []).map((id: string) => labelFn(id));
  const messagePrefix = prefix || '';
  return {
    severity: mapSeverity(issue.issue),
    message: `${messagePrefix}${issue.issueType}: ${participants}${conflictLabels.length ? ' conflicts with ' + conflictLabels.join(', ') : ''}`,
    issueType: issue.issueType,
    ...(prefix && { prefix }),
    participants,
    conflictParticipants: conflictLabels.length ? conflictLabels : undefined,
    conflictMatchUpIds: issue.issueIds?.length ? [issue.matchUpId, ...issue.issueIds] : undefined,
    matchUpId: issue.matchUpId,
    date: selectedDate,
  };
}

export function buildIssues(selectedDate: string): ScheduleIssue[] {
  // Always use allTournamentMatchUps for conflict detection — the grid cell data objects
  // lack fields that proConflicts needs to detect certain conflict types.
  const conflictResult = getCachedProConflicts(selectedDate);
  if (!conflictResult.evaluated) return [];
  const { scheduledMatchUps } = conflictResult;
  const conflictsResult = { courtIssues: conflictResult.courtIssues || {}, rowIssues: conflictResult.rowIssues || {} };

  // `severityOf` rather than a local copy: the action bar's count badge and the grid's
  // cell decoration now read the same mapping, and three private copies of it is how the
  // badge came to be red for a page of warnings in the first place.
  const mapSeverity = severityOf;

  // Build lookup from matchUpId to participant display string
  const scheduledById = new Map(scheduledMatchUps.map((mu: any) => [mu.matchUpId, mu]));
  const matchUpLabel = (id: string): string => {
    const m: any = scheduledById.get(id);
    if (!m) return 'Unknown';
    const names = (m.sides || []).map((s: any) => s.participant?.participantName ?? s.participantName).filter(Boolean);
    return names.length ? names.join(' vs ') : m.roundName || 'TBD vs TBD';
  };

  const issues: ScheduleIssue[] = [];

  // Deduplicate: for mirror pairs (A conflicts with B, B conflicts with A),
  // keep only the first occurrence by tracking seen matchUpId pairs.
  const seenPairs = new Set<string>();
  const dedupKey = (mid: string, ids: string[]): string => {
    const sorted = [mid, ...ids].sort((a, b) => a.localeCompare(b));
    return sorted.join('|');
  };

  for (const [, courtIssues] of Object.entries(conflictsResult.courtIssues || {})) {
    for (const ci of courtIssues as any[]) {
      const key = dedupKey(ci.matchUpId, ci.issueIds || []);
      if (seenPairs.has(key)) continue;
      seenPairs.add(key);
      issues.push(buildIssueEntry(ci, mapSeverity, matchUpLabel, selectedDate));
    }
  }

  for (const [rowIdx, rowIssues] of Object.entries(conflictsResult.rowIssues || {})) {
    for (const ri of rowIssues as any[]) {
      const key = dedupKey(ri.matchUpId, ri.issueIds || []);
      if (seenPairs.has(key)) continue;
      seenPairs.add(key);
      const rowPrefix = `Row ${Number.parseInt(rowIdx) + 1}: `;
      issues.push(buildIssueEntry(ri, mapSeverity, matchUpLabel, selectedDate, rowPrefix));
    }
  }

  return issues;
}

// ── Helpers ──

/**
 * Both catalog card badges, composed into the single element `renderCardExtra` accepts.
 *
 * Rest answers *"are these players fit to be called?"*; check-in answers *"are they actually here?"*.
 * They are independent questions and an operator scanning the catalog needs both, so neither may
 * suppress the other. Returns null only when both decline to render, so a card with nothing to say
 * still gets no empty wrapper.
 */
/**
 * What one card's hover should light up — the impure half of `relatedMatchUps.ts`.
 *
 * Resolved per hover rather than per render: both evaluators are pass-scoped and
 * released on the next microtask, so a hover costs one engine pass rather than
 * one per card in every catalog rebuild.
 */
function relatedFor(matchUpId: string, viewedDate: string | null): string[] {
  return relatedMatchUpIds(evaluateReadiness(matchUpId), evaluateRest(matchUpId, viewedDate));
}

function renderCardBadges(matchUpId: string, viewedDate: string | null): HTMLElement | null {
  const badges = [renderRestBadge(matchUpId, viewedDate), renderCheckInBadge(matchUpId)].filter(Boolean);
  if (!badges.length) return null;
  if (badges.length === 1) return badges[0];

  const wrap = document.createElement('span');
  wrap.className = 'tmx-card-badges';
  wrap.append(...(badges as HTMLElement[]));
  return wrap;
}
